import{u as w}from"./jsx-runtime-F7w9VrsA.js";const f={wordmark:"SpeakWith",links:{home:"Home",guides:"Guides",privacy:"Privacy",terms:"Terms",pricing:"Pricing"},theme:{label:"Appearance",system:"System",light:"Light",dark:"Dark"}},b={footer:{links:{home:"Home",automation:"Automation",guides:"Guides",privacy:"Privacy",terms:"Terms",contact:"Contact support"},tagline:"SpeakWith: your spoken ideas, captured as a daily document.",builtOn:{label:"Built on",components:"Apple Speech · Whisper · Parakeet · Nemotron · wav2vec2 · Silero",researchLabel:"Research",citation:"Ruan et al., ACM IMWUT (2017)",ctaUrl:"https://doi.org/10.1145/3161187"},copyrightHtml:'© {{year}} <a href="{{ikiSystemsHome}}" target="_blank" rel="noopener noreferrer">IKI Systems</a>. All rights reserved.'},localeSwitcher:{label:"Language",legalNote:"Privacy and Terms are published in English only."}},k={buyMacGumroad:"https://ikisystems.gumroad.com/l/vozgsy",subscribeMacGumroad:"https://ikisystems.gumroad.com/l/dcltnn",trialMacGumroad:"https://ikisystems.gumroad.com/l/vkaxll",ikiSystemsHome:"https://ikisystems.com/",supportContactUrl:"https://speakwith.discourse.group/about",appleTermsOfUse:"https://speakwith.ikisystems.com/terms/",applePrivacyPolicy:"https://speakwith.ikisystems.com/privacy/"},v={home:{title:"SpeakWith: Your Voice-to-Text Journal",description:"SpeakWith is a local-first voice-to-text journal for Mac, iPhone, and iPad that turns what you say into a searchable document, organised by day. Speak in one language and read the translation in another. Tuned for speech and dictation, not music or ambient sound. SpeakWith Pro on iPhone and iPad adds session titles and polish."},pricing:{title:"Pricing | SpeakWith",description:"iPhone and iPad: SpeakWith Pro adds session titles and polish, with a 7-day free trial. The Mac, sold through Gumroad, starts with a 14-day free trial, then a subscription or a one-time purchase."},automation:{title:"Automation | SpeakWith",description:"Start, stop, and control SpeakWith recording from the command line, Shortcuts, Automator, or a hotkey, via the speakwith:// URL scheme or AppleScript."},guides:{title:"Guides | SpeakWith",description:"Reference guides for SpeakWith on the Mac: what the recorder shows you, and how to read it."},guidesRecorderBadge:{title:"Reading the recorder badge | SpeakWith",description:"What the two lines at the left of the SpeakWith record bar mean: the build you are running, and your running tally of words, sentences, correction rates, and speaking pace."},guidesLiveTranscriptCorrections:{title:"Reading live transcript corrections | SpeakWith",description:"What the colors, underlines, and small badges on a live dictation line mean: the words you typed or spoke into it, the corrections SpeakWith made on its own, and the optional checks you can switch on."},guidesStatusMonitor:{title:"The floating status monitor | SpeakWith",description:"The small pill SpeakWith keeps on top while you dictate: what its five mode colors and words mean, why it needs neither the menu bar nor the Dock, and when the Dock badge stands in for it."},guidesSendToAgent:{title:"Send to agent | SpeakWith",description:"Where your checked Outline topics go when you press Send to agent: the Agent tab, from Destination through Send to agent, plus the Agent program, Arguments, and Project folder rows in Settings under Agent."},guidesOutline:{title:"Draft by voice, arrange afterwards | SpeakWith",description:"Talk in whatever order the ideas come, then drag the recordings into the order the document needs. Two before and after figures of the same five recordings, kept as plain markdown you can use anywhere."},guidesContextAwareInsertion:{title:"How typed-in words find their spacing | SpeakWith",description:"SpeakWith reads one character on each side of the cursor before it types a phrase into another app. The spacing rule, the six kinds of field it meets, and what it never reads."},guidesLanguageLearning:{title:"Practise a language aloud | SpeakWith",description:"Dictate in the language you are learning and read the translation under your own words: choosing an input and an output language, and the three limits."},guidesAiUsage:{title:"Viewing your AI usage | SpeakWith",description:"How to read AI Usage on Mac and iPhone: the percentage covers every device, the counts and bars are this Mac, and the diagram uses example figures."},guidesOllamaSetup:{title:"Set up Ollama on your Mac | SpeakWith",description:"Install Ollama, pull a chat model, and type that exact tag into SpeakWith for session titles and polish. The name has to match ollama list, colon included. Mac only."},technicalAgentLists:{title:"Project and model lists | SpeakWith",description:"How a program on your Mac fills the Project menu and the Model menu on the Agent tab of SpeakWith from Gumroad: one local call for the folders, and two ways to hand over the models."},privacy:{title:"Privacy Policy | SpeakWith",description:"Your words are yours. SpeakWith keeps recordings, transcripts, and documents on your device, with no tracking in the app. Optional AI features send transcript text only when you turn them on, and the included service on a monthly membership keeps only token totals. This website counts anonymous visits only."},terms:{title:"Terms of Service | SpeakWith",description:"The terms of service for SpeakWith, the local-first voice recorder and transcription app for Mac and iOS."},notFound:{title:"Page Not Found | SpeakWith"}},S=JSON.parse(`{"hero":{"eyebrow":"Your voice-to-text journal","headline":"Subtitles for your thoughts.","lead":"Speak your day into a clean markdown file on your Mac. Read it, edit it, share it. Each day is automatically created and opens in VS Code, Obsidian, or any tool you point at it.","leadSecondary":"Dictate into any app, read your words in another language, and see what you said about this before.","ctaPrimary":"Try SpeakWith free","ctaGhost":"See how it works","ctaIos":"See the iPhone app","note":"Available on Mac, iPhone, and iPad. Recording and transcription happen on your device, and on the Mac so does matching against your earlier sessions.","ctaDemo":"Watch it type"},"moments":{"title":"Words land as you speak, and you can edit them live.","heroImageDark":"canonical_screenshots/hero.png?v=20261113a","heroImageLight":"canonical_screenshots/hero-light.png?v=20261113a","heroAlt":"SpeakWith for Mac in live dictation: spoken words landing as transcribed lines under a live waveform, with a session title and a polished version of the take beside them, and a Related list on the right showing earlier sessions on the same subject under a short summary.","heroCaption":"Speak, and watch the subtitles for your thoughts take shape before the idea slips away.","heroPointsHeading":"Included with a monthly membership","heroPointsLead":"The AI service is built in and ready to use. If you would rather, connect your own OpenAI API key, or run a local Ollama model on your Mac.","heroPoints":[{"label":"Session titles","body":"Markdown headings that organize your day document, session by session. With the AI service, each title can be written for you automatically. Or write your own."},{"label":"Polish","body":"It tidies the finished take so it is easier to read, and shows what it touched before you apply it. You keep a clean copy, ready to archive or share."},{"label":"Related sessions","body":"Brings in your previous sessions on the same subject while you talk, so you know what you have talked about before. The AI service adds a short summary of them, in the direct Mac build."}],"heroPointsCta":"See what a membership includes"},"platforms":{"eyebrow":"Mac, iPhone, and iPad","title":"A recorder for the desk, a companion for everywhere else","sub":"SpeakWith is a voice-to-text journal. It is tuned for speech and dictation, the way a person actually talks, not for capturing music or ambient sound.","items":[{"name":"SpeakWith for Mac","tag":"The studio","body":"Live and batch recorders, audio and video import, and a choice of transcription engines. Apple on-device opens many spoken input languages; Whisper handles tough imported audio; Parakeet and Nemotron are options for live dictation, and Parakeet is also fastest when you import a whole file. Timestamps from transcription become SubRip (SRT) subtitles you can copy or export, with a plain text transcript in the same job folder. Every recording lands in your daily document, with playback you can click straight into. The direct build can also type finished phrases into the app you are already using.","points":["Live and batch recording","Hands-free standby when you want it","Type into app (direct build)","Projects with separate folders","Import audio and video (SRT and plain-text export)","Apple, Whisper, Parakeet, and Nemotron engines","Dictate in an input language, translate to an output language","Screenshots in your Markdown as HTML img or figure tags, with OCR"],"src":"","ariaLabel":""},{"name":"SpeakWith for iOS","tag":"The companion","body":"A voice recorder for when you are away from the desk. Dictate live, generate a title and tap Use to keep it, or polish a take into clean paragraphs. SpeakWith Pro includes the AI service for titles and polish, with a 7-day free trial, and the App Store shows its price. Polish marks every word it changed, so you can check the edit before you apply it. Your transcripts come along, organised by day, transcribed on-device with Apple Speech.","points":["Live dictation","Automatic titles, when you want them","Automatic polish, too","Browse and search transcripts by day","Projects with separate folders","On-device Apple Speech","Dictate in an input language, translate to an output language"],"src":"assets/screenshots/ios-live-polish.png?v=20261025b","srcLight":"assets/screenshots/ios-live-polish-light.png?v=20261025b","ariaLabel":"SpeakWith for iOS mid-recording: a generated session title, The readout, then Dad, with a Use button, the dictated lines below it in the reading view under a Session rule, then a revisions card reading 4 words changed: read out to readout, dropped ‘ha it’, with a Show changes checkbox ticked, the old words struck out beside the new ones, and an Apply button with a chevron beside it."}]},"typeIntoApp":{"id":"type-into-app","eyebrow":"Type into app","heading":"Dictate into Messages, Mail, or any app with a cursor","lead":"On the direct Mac build, turn on the recorder switch or a hotkey. SpeakWith types finished phrases into whichever app has focus.","videoSrc":"assets/demo/type-into-app.mp4?v=20260726d","posterSrc":"assets/demo/type-into-app-poster.jpg?v=20260726d","caption":"A real take: SpeakWith typing into Messages as each utterance settles.","ariaLabel":"Screen recording of SpeakWith live dictation with the typing switch on, sending spoken phrases into an iMessage conversation."},"translate":{"id":"translate","eyebrow":"Your languages","heading":"Speak in other languages","p1":"You can move between them. Practise the one you are learning, stay in the one a conversation is already using, or say a thought in the language it arrived in. What you said stays on the page, and a translation is written with it.","p2":"That is the freedom, and it is also how a real day goes. A meeting, a voice memo, or a message can be spoken as it happened and read in the language you keep for work. The day document holds both, so you can check what you said.","moreLabel":"Choosing which language you speak and which you read","morePath":"guides/language-learning"},"liveEdit":{"id":"live-edit","eyebrow":"Live dictation","heading":"Fix lines as they land","lead":"Wrong word? Wrong line? Edit or remove it while you are still recording. The line shows track changes, so you can see what you changed. No need to wait for a finished take.","items":[{"src":"assets/screenshots/live-edit-remove.png?v=20260801a","caption":"Drop a line that does not belong with the minus tool, still mid-session.","ariaLabel":"SpeakWith live dictation showing a line marked for removal: This line does not belong here, with the minus control highlighted beside the timestamp."},{"src":"assets/screenshots/live-edit-inline.png?v=20260801a","caption":"Tap a line, fix the wording, save. The take keeps going.","ariaLabel":"SpeakWith live dictation with one line open for inline editing: the text The metering is at tree o'clock is in an edit field with Save and Cancel, while recording continues."}]},"voiceExamples":{"id":"voice-examples","eyebrow":"Corrections","heading":"Additional layers of control over what gets written","intro":"Recognition is never perfect, so SpeakWith adds a few of its own on top of the engine. Each one decides a little more of what actually reaches the page.","exampleTitle":"Teach tricky terms by voice.","lead":"Some terms come back wrong every time you say them, usually names and jargon. Record a few readings of one and SpeakWith keeps them as reference sound. Each example shows what the engine actually heard. That gives SpeakWith more ways to spot the word, and shows you whether one it keeps missing can be corrected at all.","item":{"src":"assets/screenshots/voice-examples.png?v=20260828a","caption":"Add the term, record a few readings, and see what each one was heard as.","ariaLabel":"The SpeakWith Voice Examples pane: a list of special terms on the left, the term Nguyen selected on the right, each recorded example showing a Heard as line beneath it, and a Record Example button."},"methods":[{"title":"Special terms","body":"Some words are not spelled the way they sound. Worcestershire is one. List the names and jargon you rely on and live dictation watches for them, widening how each one can be matched so it survives more than one pronunciation. Others are harder still: Siobhan is spelled by Irish rules rather than English ones, so its letters do not map onto English sounds at all. For those you can point a spoken cue at the word instead and say Sierra Bravo to write it. Every substitution that fired is listed in a report."},{"title":"Hallucination gate","body":"Voice detection on its own cannot always tell a breath from a word, and a recognizer handed one can return a word you never said, sometimes a Yeah or an Okay. The gate waits for the written text, then blocks activations that were never meant as speech. New filler goes on the block list as you meet it, so it stops reaching the page."}],"moreLabel":"See what each correction looks like on the line.","morePath":"guides/live-transcript-corrections"},"screenshots":{"title":"More of the Mac app","subtitle":"Recordings, daily document, playback, and projects","items":[{"src":"assets/screenshots/type-into-combo.png","caption":"Use the recorder switch or a hotkey. Words appear in whichever app you are using.","ariaLabel":"SpeakWith live dictation beside macOS Messages: the typing switch is on, and the same spoken lines appear as delivered iMessage bubbles."},{"src":"assets/screenshots/markdown.png?v=20260801a","caption":"Everything lands in a plain .md file, ready to open in any editor.","ariaLabel":"The day's dictation as a markdown file open in VS Code: a dated daily document of transcribed notes."},{"src":"assets/screenshots/click-in-transcript.png?v=20260923a","caption":"Every recording in one place, grouped by day and summarized. Click any line to jump to that moment in the original recording.","ariaLabel":"A finished recording open in SpeakWith: the Activity list on the left grouped by day with a summary under each recording, timestamped transcript sentences on the right with the current line highlighted, and a waveform with playback controls underneath."},{"src":"assets/screenshots/projects-setup.png","caption":"Set up separate projects and point each one at its own folder.","ariaLabel":"SpeakWith Settings showing several named projects, each with its own transcript folder and color."},{"src":"assets/screenshots/projects-switcher.png","caption":"Switch between projects in a click to send new work to the right folder.","ariaLabel":"The project switcher menu open, listing projects with the active one checked and color tinted."}]},"moat":{"title":"Your recordings stay on your Mac.","items":[{"label":"Local","body":"Your recordings never leave your Mac. Neither does matching: Related sessions compares what you are saying with your earlier days using a model and an index that both live on your Mac. Optional session titles, polish, and the short summary above the Related list send transcript text, never audio, and only when you switch them on. A monthly membership includes an AI service for that text; otherwise it can run on a local Ollama model or an OpenAI API key you provide. On iPhone and iPad, SpeakWith Pro includes that service for titles and polish.","isHtml":false},{"label":"Markdown","body":"One plain <code>.md</code> file per day, sorted into year, month, and day folders automatically. Dictation can also go into any other Markdown file you pick. Every document uses standard headings, so it works as an outline you can rearrange. Open it in VS Code, Obsidian, or any editor.","isHtml":true},{"label":"On your computer","body":"Transcription and summarization run on your Mac. Optional AI sends the text for that step: through the service included with a monthly membership, or a key you bring.","isHtml":false}]},"inclusive":{"eyebrow":"For the AI-skeptical, too","heading":"You don't have to talk to AI to use this.","p1":"SpeakWith works on its own. Speak, get a clean markdown file, then edit it, search its text, and share it. Keep it that way for as long as you like.","p2Html":"The file is also something you can hand to an AI when <em>you</em> decide that's useful. AI is a thing the file can do, not a thing you have to do."},"features":{"title":"What SpeakWith does","items":[{"title":"A document for every day","body":"Everything you record or type on a given day flows into a single organised document, in the order it happened. That layout makes it easy to start recording your thoughts without worrying about files. Each session can carry a generated title, and those titles become the headings the Outline lists, so a long day stays easy to scan and rearrange. Apply a polished take and the clean paragraphs land where the rough ones were, while any screenshots you inserted along the way stay exactly where you put them. Tomorrow, a fresh one begins.","wide":false},{"title":"Related sessions, matched on your Mac","body":"While you talk, SpeakWith compares what you are saying with your earlier days and lists the sessions on the same subject in the AI sidebar. Click a row to open the day it came from. Matching runs on your Mac, after a one-time model download. In the direct (Gumroad) build, a short summary can sit above the list, written by the AI service included with a monthly membership, an OpenAI API key you provide, or a local Ollama model. Mac only, and off until you turn it on under Settings, Related.","wide":false},{"title":"Move between languages","body":"What you speak and what you read can differ. Your words stay on the page, and the translation is saved beneath them in the same daily document.","wide":false},{"title":"Type into app","body":"Turn on the switch in the live recorder, or set a hotkey in Settings. SpeakWith types each finished phrase into the app with focus. Available in the direct (Gumroad) Mac build.","wide":false},{"title":"Bring in audio & video","body":"Drop in a voice memo, a recorded call, or a screen recording. SpeakWith writes it up and folds it into your daily document like anything else. Transcription carries timestamps: copy or export SubRip (SRT) subtitles for an editor, and grab the plain text transcript from the job folder when you need it without cues.","wide":false},{"title":"Session titles, included or local","body":"Name each dictation session from its transcript. A monthly membership includes the AI service that writes titles and polish. Or pick an OpenAI API key you provide or a local Ollama model under Settings, Session AI. Generate is available in both the AI sidebar and the live dictation recorder when you want a heading.","wide":false},{"title":"Speak and keep working","body":"Speaking and working no longer take turns. Your dictation flows into the document on its own, so you can organise sections, paste in snippets, or type something completely different at the same time, without interrupting the words you're capturing.","wide":false},{"title":"Speaking rhythm, on screen","body":"A live meter shows the pauses inside what you are saying. Over time, that quiet feedback shapes how you speak: you hold a topic together longer, and the text on the other end gets easier to work with.","wide":false}]},"parallel":{"eyebrow":"Work at twice the pace","heading":"Like having an extra pair of hands","p1Html":"Most tools force you to shift your focus from thinking to operating an application. SpeakWith removes <em>that</em> friction. Every recorder lives in the same application, and what you capture writes out to the project you have selected.","p2":"You can control SpeakWith with a remote microphone, so you never need to touch the keyboard, and there is no key to remember before you start recording. On the direct build, turn on the recorder switch or a hotkey and speak into the app you are already in."},"rhythm":{"eyebrow":"Practice, every time you speak","heading":"The longer you use it, the better you speak.","p1":"While you record, a small meter shows the pauses inside what you are saying. Over weeks, the effect adds up. You notice when a thought starts to fragment, you stay on a topic a beat longer, and the next time you do it a little more cleanly. Instant feedback on “uh”, “um”, and other filler words trains you to drop them faster. The longer you use it, the more your speaking and your writing improve.","p2":"The text on the other end changes too. Single topics arrive in coherent pieces, and paragraphs hold together, so your daily document is something you can hand to a person or a tool without reshaping it first."},"homebase":{"eyebrow":"Built for how real work happens","heading":"The home base your thinking returns to","p1":"Real work runs in parallel. You start something that takes time to come back: a long process, a tool working away, a task you've handed off. Instead of waiting, you begin the next thing, then another. Before long, several are in flight at once.","p2":"Tools come and go; your daily document stays. It is the one place that holds every thread in a single file that is yours: what each one is for, where you left it, what to check when it lands. You can keep many things moving at once because you are not holding them all in your head."},"metrics":{"eyebrow":"On the recorder","heading":"Measure your effectiveness","leadHtml":"Speech is faster than typing, and the research is specific about how much. Ruan et al., ACM IMWUT (2017), measured speech about 3x faster than an iPhone keyboard for short messages: 153 words per minute spoken against 52 typed, counting the time spent fixing mistakes. <em>A desktop keyboard is faster than a phone keyboard, so read that multiple as the phone case.</em>","items":[{"title":"Correction rate","body":"The share of dictated words you went back and changed. <em>It only counts corrections you actually made, so the true error rate may be higher.</em>","isHtml":true},{"title":"Special terms","body":"The share of words your special terms corrected. Names, terminology, and words you pronounce your own way. The denominator is the words you dictated, the same count the correction rate uses.","isHtml":false},{"title":"Speaking pace","body":"Your words per minute of actual speech. <em>The pauses while you think are in neither half of the figure, so this is how fast you talk and not how much you get down in an hour.</em>","isHtml":true},{"title":"Audio quality","body":"A score for how well the recognizer is hearing you, on your own audio. <em>How it is measured depends on the engine you run, and the guide explains each.</em>","isHtml":true}],"totals":"Words, sentences and characters since you last reset the count: everything you said instead of typing it.","guide":{"label":"Read the recorder badge guide","path":"guides/recorder-badge"}},"faq":{"title":"Frequently asked questions","items":[{"q":"Does SpeakWith need an internet connection?","a":"No. Recording, transcription, organising your daily document, and searching its text all happen on your Mac. SpeakWith does its core work offline. Related sessions on the Mac matches offline too, once its matching model is on your Mac: that is a one-time download under Settings, Pipeline, AI Models. Only the optional AI features need a connection, and only when you turn them on."},{"q":"Can the optional AI features run locally?","a":"On the Mac, yes. Related sessions always matches locally: the model and the index it searches both live on your Mac, and no setting sends that step anywhere. Session titles stay local when you choose Ollama under Settings, Session AI, and so does the short summary above the Related list when you choose On this Mac under Settings, Related. That summary is in the direct (Gumroad) Mac build. A monthly membership includes a cloud AI service for titles, polish, and the Related summary instead, and you can also use an OpenAI API key you provide. On iPhone and iPad, SpeakWith Pro includes that service for titles and polish. They are optional, and they are not local. Core recording and transcription never need the network."},{"q":"Where are my recordings and documents stored?","a":"As ordinary files on your Mac. Open, copy, back up, or delete them with any tool you like."},{"q":"How accurate is the transcription?","a":"Automatic transcription is very good but never perfect. Names and specialist terms are the usual places small errors appear. Your daily document is fully editable, so treat the transcript as an excellent first draft you can correct.","moreLabel":"See how the recorder reports your correction rate.","morePath":"guides/recorder-badge"},{"q":"Does using SpeakWith change how I speak?","a":"It can, through quiet feedback. While you record, a small meter shows the pauses inside what you are saying, including each “uh” and “um”, something you can glance at without breaking your train of thought. Watching those marks as you speak is what changes the habit: the same fillers keep appearing on the meter, session after session, until you stop saying them. Over weeks, you may hold a topic together longer and let it land in a single, coherent piece. Your daily document gets easier to work with, and so can the way you speak to people away from the screen."},{"q":"Can I import audio and video I already have?","a":"Yes. Import a voice memo, a recorded meeting, or a screen recording, and SpeakWith writes it up the same way it writes up a live recording."},{"q":"Can I keep working while a recording is written up?","a":"Yes. That is one of SpeakWith's best features. Type and paste into the day's document while dictation is still processing; everything ends up in the correct chronological order."},{"q":"Can I dictate into other apps?","a":"Yes, on the direct (Gumroad) Mac build. Turn on the recorder switch, or set a hotkey in Settings. SpeakWith types each finished phrase into whichever app currently has keyboard focus. Your daily document still receives everything as usual. The sandboxed App Store build cannot do this; macOS does not allow cross-app typing from sandboxed apps."},{"q":"Is there an iOS app?","a":"Yes. SpeakWith for iOS is on the App Store for iPhone and iPad. Live dictation, day documents, search, and projects are free. SpeakWith Pro adds session titles and polish, with the AI allowance included and a 7-day free trial; the App Store shows the price in your currency. It transcribes on-device with Apple Speech, and it works alongside the Mac app rather than replacing it.","moreLabel":"See where that allowance shows on iPhone and Mac.","morePath":"guides/ai-usage"},{"q":"I use a Mac and an iPhone. Which should I buy?","a":"Either. Buy SpeakWith Pro on the App Store or SpeakWith for Mac on Gumroad, open the app on each device signed in to the same Apple Account, and Pro follows through iCloud. A monthly membership on either store includes the AI allowance everywhere; the one-time Gumroad license unlocks Pro on all your devices, custom themes included, with your own OpenAI key.","moreLabel":"See how that allowance is counted across your devices.","morePath":"guides/ai-usage"},{"q":"On iOS, the permission prompt says speech is \\"sent to Apple\\". Is my voice uploaded?","a":"No. That line is Apple's standard wording for the speech-recognition permission, shown to every app that asks for it. SpeakWith transcribes on-device using Apple's built-in dictation: your audio is turned into text on your iPhone or iPad. The only thing that downloads is the speech model itself, once. After that, transcription runs on your device."},{"q":"What languages does SpeakWith support?","a":"On the direct Mac build and the iPhone app, Apple Speech opens many spoken input languages: choose the one you dictate in, and pick an output language when you want a translation underneath. On Mac, Parakeet and Nemotron are additional live engines if you prefer them to Apple. The Mac App Store build does not include those engines or language menus."},{"q":"Is this an audio recorder?","a":"It is a recorder for the words you speak and want turned into text. Think of it as a voice-to-text journal. SpeakWith is tuned for speech and dictation, the way a person actually talks, so it does its best work on the human voice. It is not built for capturing music or ambient sound."},{"q":"Is the Mac download signed and checked by Apple?","a":"Yes. The direct Mac download is signed with our Apple Developer ID, so the apps you install match the build we shipped. Before upload, Apple's notary service scans that submission for known malicious software and for code-signing problems, and we staple the ticket so Gatekeeper can check it. That scan is not an App Store review, and it is not a promise that the software is free of malware."},{"q":"Where can I ask questions or suggest features?","a":"The SpeakWith Community is a new forum, still small and growing along with the app. Ask how to do something, suggest a feature, or share how you use SpeakWith; early posts help shape what comes next. For anything about your licence or a purchase, message the staff there privately instead of posting, since topics are public.","moreLabel":"Visit the SpeakWith Community","moreUrl":"https://speakwith.discourse.group/"}]},"download":{"heading":"Get SpeakWith","body":"SpeakWith runs on a Mac with Apple Silicon (M1 or later) and macOS 26 (Tahoe) or later. Download it, grant microphone access, and your first recording is a click away. The iPhone and iPad app needs iOS 26 or later.","ctaPrimary":"Get SpeakWith Pro for Mac","ctaSecondary":"iPhone and iPad on the App Store","ctaBuyOnce":"Prefer to buy once? Get a one-time license instead."},"iosScreenshots":{"title":"What the iPhone app does","subtitle":"Record a thought, file it under a project, then read, polish and replay it","items":[{"src":"assets/screenshots/ios-live-recording.png?v=20261105a","caption":"Words appear as you speak, with a title you can keep.","ariaLabel":"iPhone live recording: a waveform, rough text, a session title chip with Use, and the reading view.","srcLight":"assets/screenshots/ios-live-recording-light.png?v=20261105a"},{"src":"assets/screenshots/ios-transcripts-list.png?v=20261105a","caption":"A focus note sits above the days.","ariaLabel":"iPhone transcripts list: a Focus note named Bay Area Access Build above dated day rows.","srcLight":"assets/screenshots/ios-transcripts-list-light.png?v=20261105a"},{"src":"assets/screenshots/ios-projects-list.png?v=20261105a","caption":"Each project is a folder on this iPhone.","ariaLabel":"iPhone projects list: rows for Research Journal, Client Work, and Product Ideas, each path starting On My iPhone.","srcLight":"assets/screenshots/ios-projects-list-light.png?v=20261105a"},{"src":"assets/screenshots/ios-transcript-reader.png?v=20261105a","caption":"Open one section of a day document.","ariaLabel":"iPhone transcript reader: a day document opened to one section, with document markers hidden.","srcLight":"assets/screenshots/ios-transcript-reader-light.png?v=20261105a"},{"src":"assets/screenshots/ios-live-polish-v3.png?v=20261105a","caption":"Polish shows the paragraph before you apply it.","ariaLabel":"iPhone polish: a Transcript and Polish picker, polished paragraphs, and an Apply button.","srcLight":"assets/screenshots/ios-live-polish-v3-light.png?v=20261105a"},{"src":"assets/screenshots/ios-take-playback.png?v=20261105a","caption":"Play the take and find a line in it.","ariaLabel":"iPhone playback: transport controls, timestamped segments, and Find in this take.","srcLight":"assets/screenshots/ios-take-playback-light.png?v=20261105a"}]}}`),T={header:{eyebrow:"Plans & Features",heading:"Choose how SpeakWith works for you",sub:"On iPhone and iPad, recording and transcription are free, and SpeakWith Pro adds session titles, polish, and the Mac monthly membership. The Mac has no free tier yet: try every feature for 14 days, then subscribe or buy once."},table:{headers:{feature:"Feature",freeName:"Free trial",freeTag:"14 days, then locks",paidName:"Pro",paidTag:"Monthly (or iOS Pro), or buy once"},rows:{liveDictation:{feature:"Live dictation",subtitle:"Lines land as you talk, editable mid-take"},offline:{feature:"Offline by default",subtitle:"Audio never leaves your device"},engines:{feature:"Transcription engines",free:"Apple + Whisper + Parakeet + Nemotron",paid:"Apple + Whisper + Parakeet + Nemotron"},importMedia:{feature:"Import audio & video files",subtitle:"Transcribe files you already have, with timed SRT and plain text"},relatedSessions:{feature:"Related sessions",subtitle:"Earlier sessions on the same subject, matched on your Mac"},translate:{feature:"Translate a take",subtitle:"Dictate in one language and write it into another"},themes:{feature:"Custom themes",subtitle:"Style the whole app your way"},iosPro:{feature:"Pro on iPhone and iPad",subtitle:"Session titles, polish and custom themes on your phone too, through iCloud; the one-time license brings your own key there"},bestFor:{feature:"Best for",free:"Trying everything before you pay",paid:"Everyday use, with no time limit"},price:{feature:"Price",freePrice:"Free for 14 days",paidPrice:"See options ↓",paidPriceSub:"subscription, or buy once, see below"}}},engines:{heading:"Which engine does what",sub:"SpeakWith picks the right tool for the job. Here's what each engine is great at.",items:[{badge:"Trial & Pro",badgeKind:"free-paid",name:"Apple",body:"Built into macOS. Instant and offline. Many spoken input languages for dictation, ideal for quick notes and everyday use.",note:""},{badge:"Trial & Pro",badgeKind:"free-paid",name:"Whisper",body:"Maximum robustness on tough audio: accents, background noise, crosstalk.",note:""},{badge:"Trial & Pro",badgeKind:"free-paid",name:"Parakeet",body:"Live dictation and fast batch import. Words arrive as you speak; a whole imported file comes back in seconds, with excellent accuracy on clean English audio.",note:""},{badge:"Trial & Pro",badgeKind:"free-paid",name:"Nemotron",body:"Another live option alongside Apple and Parakeet. It streams as you speak, so words keep arriving at the same pace however long you talk.",note:""}]},chooser:{heading:"Buy once, use everywhere",sub:"Buy on either store. Open the app on each device signed in to the same Apple Account, and SpeakWith Pro follows through iCloud.",both:{title:"On the App Store",body:"Subscribe to SpeakWith Pro on your iPhone or iPad. The same subscription also unlocks the direct Mac download.",ctaLabel:"See SpeakWith Pro"},macOnly:{title:"Direct from Gumroad",body:"A membership, or buy once, on the Mac. Either one also unlocks Pro on your iPhone and iPad: session titles, polish and custom themes.",ctaLabel:"Start a 14-day free trial"},note:"The monthly AI allowance comes with a monthly membership on either store; a one-time Gumroad license brings your own OpenAI key for AI on every device. The free trial stays on the Mac."},channels:{heading:"Where to get SpeakWith",sub:"iPhone and iPad on the App Store. The Mac app is sold direct. Buy on either, and SpeakWith Pro follows your Apple Account: a Gumroad membership also unlocks Pro on your iPhone and iPad, and an App Store subscription also unlocks the direct Mac download.",items:[{lead:"App Store",heading:"SpeakWith Pro on iPhone and iPad",body:"Live dictation transcribes on your iPhone with Apple Speech, and your transcripts stay on hand, organised by day. Projects are free, up to 100. Session titles and polish are SpeakWith Pro, with a 7-day free trial and the monthly allowance included. The same subscription also unlocks the direct Mac download on a Mac signed in to the same Apple Account. The price is shown in the App Store.",ctaLabel:"Get the Mac app",ctaUrl:"https://ikisystems.gumroad.com/l/vkaxll",ctaSecondaryLabel:"",ctaSecondaryUrl:"",ctaTertiaryLabel:"",ctaTertiaryUrl:""},{lead:"Direct (Gumroad)",heading:"Subscribe, or buy once",body:"Unlock the direct build with a monthly membership you can cancel any time, or buy a one-time license. The membership includes the AI service for session titles and polish, with a monthly allowance; the one-time license uses your own OpenAI key. Both unlock Pro on your iPhone and iPad signed in to the same Apple Account, and both include the switch that types your dictation into other apps. Already subscribed on iPhone or iPad? Your subscription stands in for the membership here. Not sure yet? Start with a 14-day free trial. Every download is notarized by Apple.",ctaLabel:"Subscribe",ctaUrl:"https://ikisystems.gumroad.com/l/dcltnn",ctaSecondaryLabel:"Buy once",ctaSecondaryUrl:"https://ikisystems.gumroad.com/l/vozgsy",ctaTertiaryLabel:"Start a 14-day free trial",ctaTertiaryUrl:"https://ikisystems.gumroad.com/l/vkaxll"}]},allowanceGuide:{chooserLabel:"How AI Usage reads that allowance.",finePrintLabel:"The window that shows the allowance.",path:"guides/ai-usage"},finePrint:"Pro on the Mac (advanced engines, audio and video import, batch transcription, and smart formatting) is sold through a Gumroad membership or a one-time purchase. The membership includes the AI service with a monthly allowance; the one-time purchase and the free trial use an OpenAI key you provide or a local Ollama model. The 14-day trial locks until you subscribe or buy, and it does not carry to iPhone or iPad. On iPhone and iPad, SpeakWith Pro has a 7-day free trial, and the App Store lists its price.",macHeading:"Mac",ios:{heading:"iPhone and iPad",sub:"SpeakWith Pro adds session titles, polish, and the Mac monthly membership. Projects stay free, up to 100.",table:{headers:{feature:"Feature",freeName:"Free",freeTag:"No cost",paidName:"Pro",paidTag:"Monthly, or with your Mac licence"},rows:{liveDictation:{feature:"Live dictation",subtitle:"Apple Speech on the device, editable mid-take"},dayDocs:{feature:"Day documents and search",subtitle:"Your transcripts, organised by day"},projects:{feature:"Projects",free:"Up to 100",paid:"Up to 100"},titles:{feature:"Session titles",subtitle:"A heading from the take, when you ask"},polish:{feature:"Polish a take",subtitle:"Clean paragraphs, with the edits marked"},translate:{feature:"Translate a take",subtitle:"Dictate in one language and write it into another"},themes:{feature:"Custom themes",subtitle:"Style the whole app your way"},macApp:{feature:"Mac monthly membership",subtitle:"The direct Mac download, unlocked by your subscription"},allowance:{feature:"AI allowance included",paid:"Monthly"},price:{feature:"Price",freePrice:"Free",paidPrice:"Monthly via the App Store, or included with your Mac licence",paidPriceSub:"7-day free trial on the App Store."}}},mac:{heading:"Use your subscription on your Mac",step1:"Download SpeakWith for Mac from the free trial listing on Gumroad. You pay nothing there.",step2:"Open SpeakWith on your iPhone or iPad once, so your subscription syncs through iCloud.",step3:"Open SpeakWith on a Mac signed in to the same Apple Account. It finds your subscription and unlocks as the monthly membership.",note:"The listing also emails you a 14-day trial key. You can ignore it while your subscription is active.",linkLabel:"Download SpeakWith for Mac"},subscription:{heading:"Subscription details",summary:"SpeakWith Pro. Auto-renewing monthly subscription. The App Store shows the price, in your currency, before you subscribe.",trial:"7-day free trial, then it renews unless you cancel at least 24 hours before the period ends.",billing:"Payment is charged to your Apple Account. The subscription renews automatically unless cancelled at least 24 hours before the end of the period.",includes:"Included: session titles, polish, a monthly AI allowance, and the monthly membership for the SpeakWith Mac app downloaded from our website. Live dictation, day documents, search, and projects stay free.",manage:"Manage or cancel in the App Store app, under your account, then Subscriptions.",termsLabel:"Terms of Use (EULA)",privacyLabel:"Privacy Policy"}}},A=JSON.parse(`{"heading":"Automation","intro":"SpeakWith has two recorders you can drive from outside the app: Live dictation (real-time, finalised at each pause) and Live audio (voice-activated). You can start, stop, and control either one from the command line, a macOS Shortcut, Automator, or a hotkey launcher — with no extra setup. There are two equivalent ways to send a command: the speakwith:// URL scheme (simplest) and AppleScript (for scripting environments that prefer it).","sections":[{"heading":"Quick start: start recording","paragraphs":[{"text":"<p>The fastest way to begin a take is the URL scheme — one line any shell can run. Start the <strong>Live dictation</strong> recorder:</p><pre><code>open \\"speakwith://live-dictation/start\\"</code></pre><p>Prefer AppleScript? This does the same thing:</p><pre><code>osascript -e 'tell application \\"SpeakWith\\" to start recording recorder live dictation'</code></pre>","isHtml":true},{"text":"<p>Start the <strong>Live audio</strong> (voice-activated) recorder instead:</p><pre><code>open \\"speakwith://batch/start\\"</code></pre>","isHtml":true},{"text":"<p>Stop the current take (the microphone stays powered on, ready to start again):</p><pre><code>open \\"speakwith://live-dictation/stop\\"</code></pre>","isHtml":true}]},{"heading":"Full command reference","paragraphs":[{"text":"Each recorder supports ten actions. The table below shows the Live dictation recorder. For the Live audio recorder, replace “live dictation” with “batch” in the AppleScript command, and “live-dictation” with “batch” in the URL, with one exception, noted under the table. Two further commands control typing into other apps and name no recorder at all; they have their own section below.","isHtml":false},{"text":"<table><thead><tr><th>Action</th><th>AppleScript command</th><th>URL scheme</th></tr></thead><tbody><tr><td>Power on (microphone only)</td><td><code>power on recorder live dictation</code></td><td><code>speakwith://live-dictation/power-on</code></td></tr><tr><td>Power off (release the microphone)</td><td><code>power off recorder live dictation</code></td><td><code>speakwith://live-dictation/power-off</code></td></tr><tr><td>Start a take</td><td><code>start recording recorder live dictation</code></td><td><code>speakwith://live-dictation/start</code></td></tr><tr><td>Start a take, keeping the words in SpeakWith</td><td><code>start recording in app recorder live dictation</code></td><td><code>speakwith://live-dictation/start-in-app</code></td></tr><tr><td>Stop a take</td><td><code>stop recording recorder live dictation</code></td><td><code>speakwith://live-dictation/stop</code></td></tr><tr><td>Set standby on / off</td><td><code>set standby recorder live dictation enabled true</code> (or <code>false</code>)</td><td><code>speakwith://live-dictation/standby?on=true</code> (or <code>false</code>)</td></tr><tr><td>Toggle power (flip the microphone)</td><td><code>toggle power recorder live dictation</code></td><td><code>speakwith://live-dictation/toggle-power</code></td></tr><tr><td>Toggle recording (flip the take, microphone stays on)</td><td><code>toggle recording recorder live dictation</code></td><td><code>speakwith://live-dictation/toggle</code></td></tr><tr><td>Toggle standby</td><td><code>toggle standby recorder live dictation</code></td><td><code>speakwith://live-dictation/toggle-standby</code></td></tr><tr><td>Bring the app forward and show the recorder</td><td><code>focus recorder live dictation</code></td><td><code>speakwith://live-dictation/focus</code></td></tr></tbody></table>","isHtml":true},{"text":"<p><strong>The three toggle actions flip whatever the recorder is doing right now.</strong> They take no on or off argument: the recorder’s current state is the argument, read at the moment the command arrives. That is what lets a single hotkey mean both start and stop. They sit at different levels: <code>toggle power</code> holds or releases the microphone, <code>toggle recording</code> starts or ends a take with the microphone kept on, and <code>toggle standby</code> flips level mode.</p>","isHtml":true},{"text":"<p><strong>“In app” means in SpeakWith.</strong> If you have turned on typing into other apps, <code>start-in-app</code> turns it back off before the take begins, so your words land in SpeakWith rather than in whatever window happens to be in front. Plain <code>start</code> leaves that setting exactly as you left it. This is the one action with no Live audio counterpart — the Live audio recorder never types into other apps, so <code>speakwith://batch/start-in-app</code> simply does the same thing as <code>speakwith://batch/start</code>. And on any build that does not offer typing into other apps at all — the Mac App Store build, for one — the two are identical as well.</p>","isHtml":true},{"text":"<p><strong>Focus never touches the microphone.</strong> <code>focus</code> brings SpeakWith forward and opens that recorder’s pane, and that is all it does: it does not power the microphone on, start a take, or change the typing-into-other-apps switch. Bind it when you want the recorder in front of you before you decide what to do next. Running it again when SpeakWith is already frontmost changes nothing.</p>","isHtml":true},{"text":"<p>Each AppleScript command runs inside <code>tell application \\"SpeakWith\\" to …</code> — for example, <code>osascript -e 'tell application \\"SpeakWith\\" to power off recorder batch'</code>.</p>","isHtml":true},{"text":"A few things worth knowing. The directional commands are safe to repeat: running “start” while already recording, or “power on” while already on, simply does nothing. The four toggle commands are the exception, and deliberately so: sending one twice returns you to where you started. Standby only affects the recorder that is currently powered on; it never powers a recorder on by itself.","isHtml":false}]},{"heading":"Typing into other apps","paragraphs":[{"text":"Typing into other apps is the switch that sends what you say into whatever window is in front, instead of into SpeakWith. Two commands control it. Neither names a recorder: only Live dictation can type elsewhere, so there is nothing to choose.","isHtml":false},{"text":"<table><thead><tr><th>Action</th><th>AppleScript command</th><th>URL scheme</th></tr></thead><tbody><tr><td>Toggle typing into other apps</td><td><code>toggle type into app</code></td><td><code>speakwith://dictation/toggle</code></td></tr><tr><td>Turn typing into other apps on</td><td><code>set type into app enabled true</code></td><td><code>speakwith://dictation/type-into-app?on=true</code></td></tr><tr><td>Turn typing into other apps off</td><td><code>set type into app enabled false</code></td><td><code>speakwith://dictation/type-into-app?on=false</code></td></tr></tbody></table>","isHtml":true},{"text":"<p><strong>These do exactly what the in-app switch and the global hotkey do.</strong> That includes moving the recorder, not only the setting: turning typing on starts dictating (and if a take is already running, it begins a fresh recording from that point, so the dictated audio is its own file), and turning it off ends that take, unless you have asked SpeakWith to keep recording when typing stops.</p>","isHtml":true},{"text":"<p><code>toggle</code> flips the switch, so sending it twice returns you to where you started. The two <code>set</code> commands are directional and idempotent: asking for a state you are already in does nothing at all, so a script can assert “typing off” on a timer without ever interrupting a take. Both <code>set</code> forms require you to say which way: <code>set type into app</code> with no <code>enabled</code>, or the URL without <code>?on=</code>, is refused rather than assumed to mean on.</p>","isHtml":true},{"text":"<p><strong>Turning typing off is not the same as <code>start-in-app</code>.</strong> <code>set type into app enabled false</code> only turns the switch off. <code>start-in-app</code> turns it off <em>and</em> starts a take. Bind the first when you want your next words to stay in SpeakWith, the second when you want to start capturing right now.</p>","isHtml":true},{"text":"<p>On builds that do not offer typing into other apps at all, such as the Mac App Store build, all three commands are accepted and do nothing.</p>","isHtml":true}]},{"heading":"Targeting a specific build","paragraphs":[{"text":"By default these commands find SpeakWith by name. If you have more than one SpeakWith build installed, pin the exact one you want by its bundle identifier:","isHtml":false},{"text":"<pre><code>osascript -e 'tell application id \\"com.ikisystems.speakwith.macos.gumroad\\" to start recording recorder live dictation'</code></pre>","isHtml":true},{"text":"<p>The shipping bundle identifiers are <code>com.ikisystems.speakwith.macos.gumroad</code> (Gumroad), <code>com.ikisystems.speakwith.macos.appstore</code> (Mac App Store), and <code>com.ikisystems.speakwith.macos</code> (Developer ID direct download).</p>","isHtml":true}]},{"heading":"Wire it to a hotkey","paragraphs":[{"text":"Because these are ordinary commands and URLs, you can turn any of them into a keyboard shortcut today. Drop one into a macOS Shortcut, an Automator “Run Shell Script” action, or a launcher such as Raycast, Alfred, or Keyboard Maestro, and give it the hotkey you like.","isHtml":false},{"text":"<p>If the hotkey is how you begin dictating, <code>start-in-app</code> is usually the one to bind: it means “capture this here” no matter how you last left the typing-into-other-apps switch.</p><pre><code>open \\"speakwith://live-dictation/start-in-app\\"</code></pre>","isHtml":true},{"text":"<p>If your launcher would otherwise need a separate “activate the app” step first, <code>focus</code> replaces it: the command brings SpeakWith forward on its own, and it leaves the microphone alone, so a macro can put the recorder in front of you without starting a take.</p><pre><code>open \\"speakwith://live-dictation/focus\\"</code></pre>","isHtml":true},{"text":"<p>For push-to-dictate into whatever window is in front, bind the typing toggle. One key turns typing on and starts dictating; the same key turns it off again.</p><pre><code>open \\"speakwith://dictation/toggle\\"</code></pre>","isHtml":true}]}]}`),x=JSON.parse(`{"index":{"eyebrow":"Guides","heading":"Reference guides","intro":"Short explanations of what SpeakWith shows you on screen. Each guide covers one part of the app and stays close to what you see.","cards":[{"title":"Reading the recorder badge","body":"The two lines at the left of the record bar show the build you are running and a tally of your dictation: your correction rate, your special terms, and your speaking pace.","path":"guides/recorder-badge","cta":"Read the guide"},{"title":"Reading live transcript corrections","body":"The marks on a settled line of live dictation: your edits, SpeakWith's corrections, and what its optional checks found.","path":"guides/live-transcript-corrections","cta":"Read the guide"},{"title":"The floating status monitor","body":"The small pill that stays on top while you dictate: your mode in a color and a word, an optional waveform showing the mic is still hearing you, and no menu bar or Dock to keep on screen.","path":"guides/status-monitor","cta":"Read the guide"},{"title":"Send to agent","body":"Tick topics in the Outline, pick an agent, project, and model on the Agent tab, then send them as one message to a coding agent on your Mac.","path":"guides/send-to-agent","cta":"Read the guide"},{"title":"Draft by voice, arrange afterwards","body":"Talk in whatever order the ideas come. Then drag the recordings into the order the document needs, nested where they belong, and keep the result as plain markdown.","path":"guides/outline","cta":"Read the guide"},{"title":"How typed-in words find their spacing","body":"Before SpeakWith types a phrase into another app, it reads one character on each side of the cursor. The rule it applies, and the six ways a field can answer.","path":"guides/context-aware-insertion","cta":"Read the guide"},{"title":"Practise a language aloud","body":"Dictate in the language you are learning and read the translation under your own words. How the input and output languages pair up, and what the feature cannot do yet.","path":"guides/language-learning","cta":"Read the guide"},{"title":"Project and model lists","body":"For people who write programs: how a program on your Mac fills the Project and Model menus on the Agent tab.","path":"technical/agent-lists","cta":"Read the page"},{"title":"Viewing your AI usage","body":"The AI Usage window shows a percentage for the whole membership, and the counts and daily bars for this Mac. The figures in the guide are an example.","path":"guides/ai-usage","cta":"Read the guide"},{"title":"Set up Ollama on your Mac","body":"Install the local app, pull a chat model, and type that same tag into Settings, Session AI. SpeakWith does not list the models on your machine for you.","path":"guides/ollama-setup","cta":"Read the guide"}]},"recorderBadge":{"eyebrow":"Guides","heading":"Reading the recorder badge","intro":"At the left of the record bar on the Mac, SpeakWith shows two short lines in a small monospaced typeface. The first identifies the build you are running. The second tracks your dictation over time. The diagram below walks through each segment.","diagramDark":"assets/guides/recorder-status-badge-annotated.svg?v=20261014a","diagramLight":"assets/guides/recorder-status-badge-annotated-light.svg?v=20261014a","diagramAlt":"Annotated diagram of the SpeakWith recorder badge. Line one reads SpeakWith 2.14.0 Pro (app=eng 20260923.10): the app name, version, edition, and the build stamp shared by the app and its engine. Line two reads 9,834w · 1,770s · 0.7% wer · 0.1% st · 148 wpm: words and sentences dictated since the last reset, the share of words you corrected, the share your special terms corrected, and your speaking pace.","sections":[{"heading":"The first line: which build you are running","paragraphs":[{"text":"The line starts with the app name, its version, and the edition. The edition reads Pro on a direct download, or MAS if you installed SpeakWith from the Mac App Store."},{"text":"The part in parentheses is the build stamp: the build date, then the build number for that day. The app and its transcription engine are stamped together, so they normally show one value. If they ever differ, the line shows both, which is the first thing to mention if you write in about a problem."}]},{"heading":"The second line: your dictation tally","paragraphs":[{"text":"The counts are words and sentences you have dictated since the last reset, across all sessions. The s stands for sentences, not seconds. The character count used to sit on this line. It now lives in About, under Totals."},{"text":"The two percentages use the word count as their denominator. The correction rate (wer) is the share of dictated words you went back and changed, a personal stand-in for WER (Word Error Rate). It only counts corrections you actually made, so the true error rate may be higher. The special-terms rate (st) is the share of words that your own special terms corrected: names, terminology, and words you pronounce your own way, which the recognizer would otherwise get wrong."},{"text":"The last figure is your speaking pace, in words per minute of speech. The pauses while you think sit in neither half of the ratio, so this is how fast you talk. It is not how much you get down in an hour, and it is not a typing speed. The badge never divides your pace by a typing figure."}]},{"heading":"The panel header: this session","paragraphs":[{"text":"Live dictation adds a line for the session you are in. It counts settled utterances, the words in them, and the time you were actually speaking. When a score exists it adds the audio quality check, and it ends with a pace for this session. A sample line reads: 12 settled · 840 words · 6m speech · support 94.2% · ~148 wpm."},{"text":"That session pace and the badge pace use different clocks, and a gap is expected. The badge covers every session since the last reset, as words over speech time. The header covers this session, from the start of one utterance to the start of the next. On the same audio the header usually reads about a tenth higher."},{"text":"The session pace has three states. Before there is enough speech, you see a dash and then wpm. While the figure is still settling, a tilde sits in front of it (~148 wpm). Once the session has enough speech, the tilde drops off and the number stands alone."},{"text":"The support percentage joins the line only after a real score exists. If the checker is not installed, that segment is left off the line."}]},{"heading":"The audio quality check","paragraphs":[{"text":"Settings calls this the audio quality check. On the header it appears as support followed by a percentage: a score for how well the recognizer is hearing you, on your own audio. The engine you are running decides how that percentage is measured."},{"text":"On Whisper batch jobs, and on Parakeet live dictation, the percentage is an independent listener's agreement with the transcript. The listener compares phonemes, the sounds of the words, with what was written down. From strongest to weakest the bands are Strong, High, Moderate, Weak, Minimal, and None."},{"text":"Apple Speech reports the recognizer's own confidence under the same label. Its bands are High, Moderate, and Low. The names overlap and the cutoffs do not: 0.85 is High on Apple Speech and only Moderate for the phoneme listener. This guide prints no single band table for both, because one table would mix two scales."},{"text":"The bundled checker is English only. When no score exists yet, the percentage stays off the line. Live dictation waits until the checker is installed and a first utterance has been scored."}]},{"heading":"Hiding, resetting, and reading more","paragraphs":[{"text":"There is no visible control on the badge itself; the space belongs to the Record, Flush, and Power buttons. Long-press anywhere on the badge to open the About window. About holds the switch that hides or shows the tally, the reset that starts the counts again from zero, and a correction rate measured on reviewed lines only."},{"text":"In the app, hover over any segment of the badge to see the same explanation as a tooltip. The values in the diagram are sample values."}]}],"seeAlso":{"label":"See also: reading live transcript corrections, the marks on each line as it lands.","path":"guides/live-transcript-corrections"}},"statusMonitor":{"eyebrow":"Guides","heading":"The floating status monitor","intro":"While the live-direct mic is held, SpeakWith can float a small pill above every other window. It shows one colored dot and one or two words: the mode you are in right now. It can also carry a small live waveform, so the same glance tells you the mic is still hearing you. You read it from across the room, or from the corner of your eye while you type in another app, without bringing SpeakWith forward. The diagram below shows the pill, its five modes, and the one thing it cannot replace.","diagramDark":"assets/guides/status-monitor-annotated.svg?v=20261027a","diagramLight":"assets/guides/status-monitor-annotated-light.svg?v=20261027a","diagramAlt":"Annotated diagram of the SpeakWith floating status monitor: a small rounded badge sitting over another app's window. Its top row carries the SpeakWith mark, a blue dot, the words Type into app, and a smaller detail line reading Into open field. Under that row runs a live waveform strip, its bars rising and falling with speech and flattening to a line across a quiet stretch in the middle. Five numbered callouts name the mark, the mode color, the mode word, the detail line, and the waveform. Below the badge, five smaller pills show the five modes with their colors: Recording in red, Type into app in blue, Voice pull in indigo, Listening in orange, and Monitoring in green, with a note that Listening is level mode and a hardware mute switch pauses and resumes it. A row of check marks reads Menu bar hidden, Dock hidden, SpeakWith in the background. At the bottom, three app icons carry small red Dock badges reading REC, TYPE, and a pause mark, captioned as the fallback.","sections":[{"heading":"What the pill shows","paragraphs":[{"text":"Four things across the top row, left to right. The SpeakWith mark, so you know whose badge it is when it is the only thing of ours on screen. A colored dot for the mode. The mode word beside the dot, because a color on its own is easy to misread and the word settles it. And, when there is something to add, a smaller detail line, for example when your words are going into an open text field."},{"text":"The fifth thing sits under that row: a small live waveform, the same one that scrolls inside SpeakWith's own window. The dot and the word say what dictation is doing. The waveform answers the other question, the one that comes up when a take has gone quiet and SpeakWith is hidden behind the app you are typing into: is the mic hearing me? The bars rise with your voice and fall to a flat line in silence, so there is nothing to misread. The pill grows a little taller to make room, and never wider."},{"text":"The dot can pulse, fading in and out like the recording light in the sidebar: faster while recording or typing into another app, slower while listening. That is a separate switch, so you can keep the dot solid if a moving light in the corner of your eye is not what you want."}]},{"heading":"The five modes","paragraphs":[{"text":"Recording, in red: a take is running and going where it always goes, into your day document. Type into app, in blue: a take is running and being typed into whatever app is in front of you. Voice pull, in indigo: a take is running and a shell client is pulling the words instead. Listening, in orange: level mode standby, with the mic held and a take starting the moment you speak up. Monitoring, in green: the mic is held and metering, with no take running."},{"text":"Blue against red is the comparison this pill exists to make easy. Before it, recording into your document and typing into another app looked the same from a distance, and finding out which one you were in meant switching to SpeakWith. Now a glance at the pill tells you whether your next sentence lands in your document or in the email you are looking at."},{"text":"Listening is the mode to know about if your microphone has a hardware mute switch. Level mode watches the audio level rather than a button, so flipping the mute switch drops the level and pauses the recorder, and flipping it back resumes. No key, no click, no window to find: the orange dot tells you SpeakWith is waiting, and the pill going red tells you it heard you."},{"text":"When more than one applies, the pill shows the one that matters most: Voice pull first, then Type into app, then Recording. It appears only in live-direct dictation. Batch capture, and the mic being off, show no pill at all."}]},{"heading":"Nothing else to keep on screen","paragraphs":[{"text":"The pill is its own small window. It takes no slot in the menu bar, needs no Dock, and never takes keyboard focus, so it cannot steal a keystroke from the app you are typing into. You can hide the menu bar and the Dock, put SpeakWith in the background, fill the screen with the app you are working in, and the pill is still there."},{"text":"Drag it anywhere once and it stays put, on top of everything, until you power the mic off. Many people park it in a corner next to where their words are landing, so the mode and the text sit in one glance."}]},{"heading":"If you keep the Dock showing","paragraphs":[{"text":"The Dock badge is the fallback. SpeakWith's Dock icon reads REC while recording, TYPE while typing into another app, and a pause mark while listening in level mode. It is there whether or not the pill is, and it is enough if your Dock is always visible and you only need to know that a take is running."},{"text":"What it cannot do is color-code the modes: macOS paints every Dock badge the same red, whatever the word inside it. That is the reason the floating monitor exists, and the reason it, not the badge, is the one to reach for when you type into other apps."}]},{"heading":"Turning it on","paragraphs":[{"text":"Settings, Dictation, under Type into app: Show mode indicator floats the pill; Pulse the mode indicator makes the dot breathe; Waveform in the mode indicator draws the strip. The waveform is on to begin with, so switching it off is what gets you the short pill back, exactly as it was. It greys out when Show mode indicator is off, because there is no badge to draw it in. All three are in the direct-download builds of SpeakWith. The Mac App Store build keeps the Dock badge."}]}],"seeAlso":{"label":"See also: reading the recorder badge, the two lines at the left of the record bar.","path":"guides/recorder-badge"}},"liveTranscriptCorrections":{"eyebrow":"Guides","heading":"Reading live transcript corrections","intro":"Once a line of live dictation settles, SpeakWith can mark it in two ways. Inside the line, color and underlines show which words you changed yourself. After the line, small badges show what SpeakWith corrected on its own and, if you have switched them on, what its extra checks found. Most lines carry no marks at all. The diagram below shows one line with every kind of mark on it.","diagramDark":"assets/guides/live-transcript-corrections-annotated.svg?v=20260929g","diagramLight":"assets/guides/live-transcript-corrections-annotated-light.svg?v=20260929g","diagramAlt":"Annotated diagram of one settled live dictation line in SpeakWith, a portrait photographer's note between sittings. The line reads: Edit the first three headshots, then call Aaliyah before Okafor's sitting. The word first is struck through and faded because it was deleted. The word three is in the typed-words color over a pale band because it was typed in to replace tree. The words then call sit on a pale band with a dotted underline because they were dictated into the line. The word headshots is plain because the recognizer wrote it. Three badges trail the text: a Special Terms rewrite reading alia to Aaliyah, a Voice Examples correction reading Akheffer to Okafor, and a green check mark from the second pass.","sections":[{"heading":"Marks inside the line","paragraphs":[{"text":"The line you see is not always the line you spoke. You can open any settled line and fix it with the keyboard, or dictate a phrase straight into it, and the day document keeps the result. Playback, though, still plays the original audio. So each word is painted by where it came from, and the words the recognizer wrote stay plain.","isHtml":false},{"text":"<table><thead><tr><th>Mark</th><th>What it means</th></tr></thead><tbody><tr><td>Typed words</td><td>Your typed-words color, over a pale band of the same hue. If you said <em>three headshots</em> and the line came back as <em>tree headshots</em>, opening it and typing <em>three</em> marks only <em>three</em>.</td></tr><tr><td>Dictated into a line</td><td>The text keeps its normal color, sits on a pale band of the spoken-into-line color, and takes a dotted underline in a complementary shade. Open a line, speak a phrase, and the phrase lands marked this way.</td></tr><tr><td>Deleted words</td><td>Still visible, struck through and faded, like tracked changes in a word processor. A line you removed entirely is struck through as a whole and dimmed.</td></tr><tr><td>Plain words</td><td>The recognizer wrote them and nobody changed them. No color, no band.</td></tr></tbody></table>","isHtml":true},{"text":"Both colors are yours to choose under Settings, Playback: Typed words and Spoken-into-line. The band and the dotted underline are derived from the color you pick, so the two families stay distinct at a glance.","isHtml":false},{"text":"Only your own edits are painted. When SpeakWith joins two spans into one sentence, or a second engine re-reads a line, those words were all spoken, so they stay plain.","isHtml":false}]},{"heading":"Badges after the line: corrections SpeakWith made","paragraphs":[{"text":"A badge trails the text of the line it belongs to. There is no reserved column, so a line with nothing to report looks exactly like every other line. When several corrections land on one line, they share a badge, separated by commas. Hover over any badge to read a full explanation.","isHtml":false},{"text":"<table><thead><tr><th>Badge</th><th>Meaning</th></tr></thead><tbody><tr><td><code>↦ alia → Aaliyah</code></td><td>A rewrite from your Special Terms list. The first arrow marks the list, and the second reads heard, then written: the recognizer wrote <em>alia</em>, and your rule for the name Aaliyah replaced it. This layer is always on: the badge appears whenever a listed term was rewritten, whatever mode the recorder is in.</td></tr><tr><td><code>Akheffer → Okafor</code></td><td>The term spotter heard one of your special terms in the audio and corrected the line to match. The arrow means the text changed.</td></tr><tr><td><code>Nguyen</code></td><td>The spotter heard a term but the line was not changed: usually the term was already spelled correctly, or correcting is switched off. The tooltip says which.</td></tr><tr><td><code>⚡ Akheffer → Okafor</code></td><td>The match came from one of your Voice Examples, a recording of you saying the name, rather than from its spelling. The bolt is reserved for that. Okafor is the kind of name that earns one: no spelling rule covers how it is misheard.</td></tr></tbody></table>","isHtml":true},{"text":"The spotter is set up under Settings, Corrections. Show spotted special terms hangs the badge on every line where a term was heard. Correct spotted special terms in the line lets the spotter change the text, and a badge with an arrow appears whenever it does, so a correction never lands silently.","isHtml":false}]},{"heading":"An optional second opinion","paragraphs":[{"text":"One more check can run on each line. It is off by default and lives under Settings, Debug, because it is for understanding the engines rather than for everyday dictation. When it is on, one more glyph trails the line.","isHtml":false},{"text":"<p>The second pass re-reads short lines with a second engine and reports with a single character.</p><table><thead><tr><th>Glyph</th><th>Meaning</th></tr></thead><tbody><tr><td><code>…</code></td><td>Queued. The second engine reads the line again once the take stops.</td></tr><tr><td><code>✓</code></td><td>Green. The second engine heard the same words.</td></tr><tr><td><code>≠</code></td><td>The second engine heard something different. A row appears beneath the line with the other reading, so you can compare the two.</td></tr><tr><td><code>?</code></td><td>Orange. The second engine returned nothing, or could not read the audio. Its model may be missing or still loading.</td></tr></tbody></table>","isHtml":true},{"text":"The switch is Show second-pass diagnostics. It never changes what is written. It only shows what happened.","isHtml":false}]},{"heading":"When nothing appears","paragraphs":[{"text":"An unmarked line is the normal case, and it can mean several things. The recognizer got the line right and nobody changed it. A special term was already spelled correctly, so there was nothing to correct. Or the second pass is simply switched off, so its glyph draws nothing.","isHtml":false},{"text":"If you expected a correction and see no badge, check the two spotter switches under Settings, Corrections first, then that the term is in your Special Terms list or has a Voice Example.","isHtml":false}]}],"seeAlso":{"label":"See also: reading the recorder badge, which reports your correction rate over time.","path":"guides/recorder-badge"}},"sendToAgent":{"eyebrow":"Guides","heading":"Send to agent","intro":"Send to agent takes the topics you have checked in the Outline and hands them, as one message, to a coding agent running on your Mac. The agent is connected over ACP, the Agent Client Protocol, and that connection is what lets SpeakWith ask the agent which folder to work in and which model to use, so you choose both from a menu instead of typing them. This page follows one job from the Outline through to the message the agent receives.","examplesLabel":"In this job","diagramDark":"assets/guides/send-to-agent-annotated.svg?v=20260929g","diagramLight":"assets/guides/send-to-agent-annotated-light.svg?v=20260929g","diagramAlt":"Annotated diagram of the two panels behind Send to agent in SpeakWith. The upper panel is the Destination block from the Agent tab: three labelled rows reading Agent, Project, and Model, each with a pop-up menu, and an Add folder button beside Project. Beneath it the Project menu is shown opened, with a Recent section listing folders and when they were last used, and an All projects section listing the rest. The lower panel is the program block of Settings under Agent: an Agent program row showing a file path with a Change button and a small minus, an Arguments text field, and a Project folder row showing a folder path with the same Change button and minus. Numbered callouts name each control.","sections":[{"heading":"Before you start","paragraphs":[{"text":"You need one coding agent installed on this Mac, such as Claude Code, Cursor, Codex, or Gemini. If you use a session manager that publishes its projects to SpeakWith, have it running. That is all. If the agent you want is not one SpeakWith finds on its own, see Point SpeakWith at a program of your own, near the end of this page."}],"steps":[]},{"heading":"The job","paragraphs":[{"text":"This morning you dictated a session about chapter 4 of a book. The manuscript lives in a folder named lighthouse-book. Two Outline rows belong in that chapter. A third row, The lamp oil, stays unchecked."}],"figureDark":"assets/guides/send-to-agent-outline.svg?v=20260929g","figureLight":"assets/guides/send-to-agent-outline-light.svg?v=20260929g","figureAlt":"The Outline with three rows. The storm scene and Names to keep have filled circles. Names to keep says the keeper is Mara Voss. The lamp oil has an empty circle and is not sent.","figureWidth":1280,"figureHeight":560,"steps":[]},{"heading":"Send checked topics to an agent","paragraphs":[{"text":"Destination is already set in the figure at the top of this page. On that same tab, the two topics, the instruction, and Send to agent sit together."}],"figureDark":"assets/guides/send-to-agent-block.svg?v=20260929g","figureLight":"assets/guides/send-to-agent-block-light.svg?v=20260929g","figureAlt":"The Agent tab, ready to send. The status line reads Claude Code, lighthouse-book, default model. A caption says 2 topics will be sent as one prompt turn. Preview tiles show The storm scene and Names to keep. The instruction names chapters/04-the-storm.md and forbids a new character. A blue Send to agent button is under that box. Callouts name the status line, the caption, Optional instruction, and the button.","figureWidth":1480,"figureHeight":860,"steps":[{"title":"Check the topics.","text":"In the Outline, tick each topic you want the agent to see. Until at least one is checked, Send to agent stays disabled, and the Agent tab reads: Check topics in the Outline to preview what the agent will receive.","examples":["Tick The storm scene and Names to keep. Leave The lamp oil empty.","Clear every circle and Send to agent stays disabled."]},{"title":"Open the Agent tab.","text":"In the sidebar, choose Agent, beside Session, Feedback, and Stores. Destination is at the top of that tab. Send to agent follows it.","examples":["Open Agent, beside Session, Feedback, and Stores. The tooltip reads: Hand the selected session to an agent."]},{"title":"Pick an Agent.","text":"Open the Agent menu and choose who should receive the topics. The status line starts with that name, or reads not configured when nothing resolves.","examples":["Choose Claude Code. The status line on the Agent tab starts with that name, then lighthouse-book, then default model.","If nothing resolves, that same line reads not configured."]},{"title":"Pick a Project.","text":"Open the Project menu and choose the folder the agent should work in, from Recent, All projects, or Add folder…. The middle of the status line should name that folder.","examples":["Choose lighthouse-book from Recent. It shows 2 h ago because the manuscript was open then.","field-notes is also on the poster at the top of this page. It is research, so it is the wrong folder.","If lighthouse-book is missing, Add folder… selects it. The middle of the status line should then read lighthouse-book."]},{"title":"Leave Model alone, or choose one.","text":"Model stays on Agent default until the agent has reported its own list. The status line then ends in default model, so the agent picks for itself.","examples":["Leave Model on Agent default. The status line ends in default model, and Claude Code chooses.","Open the menu later only if you want a smaller model for a second pass on the same two topics."]},{"title":"Add an instruction, if you like.","text":"On the Agent tab, the Optional instruction box is where you say what to do with the topics. Leave it empty and only the checked topics are sent.","examples":["The box on the Agent tab names chapters/04-the-storm.md and forbids a new character. The two topics do not say either of those things.","Leave the box empty and both topics still go, with no file to create."]},{"title":"Press Send to agent.","text":"Nothing is handed over until this press. Read the topics caption on the Agent tab first, and treat that line as the confirmation.","examples":["The caption reads: 2 topics will be sent as one prompt turn. Press Send to agent only after you see that line. The next section is the message that press builds."]}]},{"heading":"The message","paragraphs":[{"text":"With a session manager, that press builds one prompt. SpeakWith opens with a lead line, your instruction follows, then each checked topic under its own heading."}],"figureDark":"assets/guides/send-to-agent-message.svg?v=20260929g","figureLight":"assets/guides/send-to-agent-message-light.svg?v=20260929g","figureAlt":"The prompt handed to Claude Code. It opens with the SpeakWith lead line, then the instruction to write chapter 4 as chapters/04-the-storm.md, then The storm scene and Names to keep. Names to keep says the keeper is Mara Voss and the supply boat is Cormorant.","figureWidth":1100,"figureHeight":760,"steps":[]},{"heading":"The terminal","paragraphs":[{"text":"Open a session opens this window on lighthouse-book. Claude Code runs the prompt from the section above and writes chapters/04-the-storm.md in that folder."}],"figureDark":"assets/guides/send-to-agent-terminal.svg?v=20260929g","figureLight":"assets/guides/send-to-agent-terminal-light.svg?v=20260929g","figureAlt":"A terminal window titled lighthouse-book, Claude Code. It is running the SpeakWith prompt, then shows Wrote chapters/04-the-storm.md. The file contains the storm scene and the keeper Mara Voss, taken from the notes.","figureWidth":1480,"figureHeight":840,"steps":[]},{"heading":"Rows you may or may not see","paragraphs":[{"text":"Two more rows appear under Destination only when there is a choice to make."}],"steps":[{"title":"Terminal.","text":"This row is there only when this Mac has more than one terminal app. Choose which one should open.","examples":["This job needs a window you can watch. With one terminal app installed, Destination has no Terminal row, and that app is the one that opens on lighthouse-book.","With two terminal apps installed, pick the one that should show Claude Code creating chapters/04-the-storm.md."]},{"title":"Runs in.","text":"You see Runs in only for SpeakWith's own bridge. Open a session watches a terminal window; Answer here puts the reply on the Agent tab.","examples":["Choose Open a session. The terminal figure is Claude Code writing the chapter in lighthouse-book.","Answer here would put the draft on the Agent tab instead. On that path SpeakWith declines a request to create chapters/04-the-storm.md."]}]},{"heading":"If you press Send twice","paragraphs":[],"steps":[{"title":"With your session manager chosen.","text":"A second press on the same topics is held: the Agent tab says they were already sent, and Send again repeats them. The Sent ledger, lower on that tab, keeps the list.","examples":["Three minutes later the same two topics are still checked. The Agent tab reads: Already sent 3 minutes ago. Send again is what would hand chapter 4 over a second time.","The Sent ledger, lower on the Agent tab, lists that send. Before the first press it read: Nothing sent yet from this tab."]},{"title":"With any other agent chosen.","text":"Every press is a fresh message, with no hold. The Outline checkboxes are still what gets sent.","examples":["This job used the session manager, so the hold above applies. An agent that is not that manager does not hold.","On that other path, a second press sends The storm scene and Names to keep again. Uncheck Names to keep first if the repeat should carry only the scene."]}]},{"heading":"Point SpeakWith at a program of your own","paragraphs":[{"text":"Skip this section when Claude Code is already in the Agent menu. When the agent that should write the chapter is missing from that menu, Settings, under Agent, holds the three rows for a program of your own: Agent program, Arguments, and Project folder. How such a program fills the Project menu and the Model menu is on its own page."}],"linkLabel":"Read how a program fills the Project and Model lists.","linkPath":"technical/agent-lists","steps":[]},{"heading":"What the agent can and cannot do","paragraphs":[{"text":"In this job you chose Open a session, so Claude Code runs in a terminal in lighthouse-book and writes the chapter there. Answer here is the other choice: the draft comes back onto the Agent tab, and SpeakWith declines a request, made through that connection, to change files on the Mac."}],"steps":[]}],"seeAlso":{"label":"See also: Project and model lists, how a program of your own fills the Project menu and the Model menu.","path":"technical/agent-lists"}},"outline":{"eyebrow":"Guides","heading":"Draft by voice, arrange afterwards","intro":"You do not have to know where everything goes before you start talking. Record each idea as it comes, in any order. Every recording lands in the day document as its own section, and the Outline lets you drag those sections into the order the document needs, nested where they belong. The words stay exactly what you said, and the result is plain markdown, so the draft is already in a form every editor can open. This page shows the two moves a drag can make, an indent and a reorder, each as a before and after of the same five recordings.","diagramDark":"assets/guides/outline-feature-annotated.svg?v=20260930c","diagramLight":"assets/guides/outline-feature-annotated-light.svg?v=20260930c","diagramAlt":"SpeakWith Outline poster. The wordmark is at the top right and on each figure. Two before and after figures of the same five recorded text blocks. Each block shows a recorded time, a short heading, and one or two lines of spoken words. A curved arrow runs from the moved block on the left to its new place on the right. Figure 1: the second recording is nested one step under the first, a dashed outline marks where it sat, and the order is unchanged. Figure 2: the fifth recording has moved up between the second and the third, and nothing is indented. The words are the same on both sides.","captions":[{"label":"Figure 1. Indent.","text":"The second recording is nested under the first. The spoken order is unchanged, and so is every time."},{"label":"Figure 2. Reorder.","text":"The fifth recording moves up between the second and the third. Nothing is indented."}],"sections":[{"heading":"Record first, arrange second","paragraphs":[{"text":"Spoken ideas arrive in time order. A finished document is in topic order. The Outline is the bridge between the two: every row is one recording, with the time you started speaking and the words you said, and a drag changes neither. It changes only where the recording sits in the day document: under another recording, or earlier or later in the day. Keep each recording to one idea and you will have more to arrange."}]},{"heading":"Indent","paragraphs":[{"text":"Drop a row toward the right edge of the row above it and it nests one step under that row. Figure 1 nests the second recording under the first. The spoken order is unchanged, and so is every time. A row nests one step at a time; a drop that would skip a level is refused."}]},{"heading":"Reorder","paragraphs":[{"text":"Drop a row between two others and it moves there, still at the same level. Figure 2 moves the fifth recording up between the second and the third. Nothing is indented. The day document keeps a recording's time marker only where the times still read in order, so a recording moved ahead of earlier ones drops its marker there. The words are untouched."}]},{"heading":"Apply and Undo","paragraphs":[{"text":"A drop is a preview. The Outline shows the new arrangement at once, but nothing on disk changes until you press Apply, which writes the arrangement to the day document. Undo takes back the last drag. Drops you never apply change nothing."}]}],"seeAlso":{"label":"See also: Send to agent, which takes the Outline rows you have checked to a coding agent on your Mac.","path":"guides/send-to-agent"}},"contextAwareInsertion":{"eyebrow":"Guides","heading":"How typed-in words find their spacing","intro":"A phrase typed into another app sometimes lands with no space before it, or with two. SpeakWith avoids both by looking at the two characters around the cursor before it types, and this page explains that look: what it reads, what it decides, and the six ways a field can answer, from a field that reports everything to one that collapses spacing after the fact.","diagramDark":"assets/guides/context-aware-insertion-annotated.svg?v=20261005a","diagramLight":"assets/guides/context-aware-insertion-annotated-light.svg?v=20261005a","diagramAlt":"SpeakWith poster in two figures. Figure A, what it looks at: four rows, each a text field with a cursor, the same spoken word, and the result. The one character before the cursor and the one after it are circled and joined by thin leader lines to a label that reads one before, one after. Row one, cursor after a word: one space is added. Row two, cursor after a space: no space is added. Row three, cursor before a period: the word goes in with no space on either side. Row four, a selected word: the spoken word replaces it and the spacing comes from the characters outside the selection. Figure B, when the field will not say: four panels. Legible, Opaque, and Silent each show two phrases landing in the same field with the spacing each kind of field gets. Trimming shows a leading space pasted and eaten, then the same space typed as a keystroke and kept.","captions":[{"label":"Figure A. What it looks at.","text":"One character before the cursor, one after. Against a word, one space. Against a space, an edge, or closing punctuation, none. A selection is read from its outside."},{"label":"Figure B. When the field will not say.","text":"A legible field gets the full rule. An opaque or silent field gets start-of-field spacing plus the join space between phrases. A trimming field keeps its space because the space is typed, not pasted."}],"sections":[{"heading":"What it looks at","paragraphs":[{"text":"Before SpeakWith types a finished phrase, it asks the app in front for two characters: the one immediately before the cursor and the one immediately after. Nothing else is read. From those two it decides the spacing, and the rule is short. If the character before is part of a word, the phrase gets one space in front. If it is a space, nothing is added. If there is nothing before the cursor at all, nothing is added either. The same applies after the phrase: one space if a word follows, none if a space or closing punctuation follows, so a phrase typed in front of a period sits snugly against it."},{"text":"Two details matter more than they look. First, the start of a field and a field that could not be read are treated the same way, on purpose: in both cases SpeakWith adds nothing in front and lets the phrase itself carry its spacing, so a read that fails never turns into a stray space. Second, a hyphen or an underscore before the cursor counts as already joined, so a field that ends in well- gets well-known, not well- known. If you select a word before you speak, the phrase replaces the selection and the two characters are read from outside it, as Figure A shows in its last row."}]},{"heading":"Why it is one space, never two","paragraphs":[{"text":"With Punctuation off, each phrase SpeakWith types ends in one space, so consecutive phrases read as running prose. That join space exists because, for a long time, typing into another app could not see the field at all. When the field can be read, the join space is dropped and the two-character rule decides instead, since keeping both would put two spaces at the seam. When the field cannot be read, the join space is kept, and the next phrase lands after it exactly as it always did. With Punctuation on, your spoken periods and question marks do the separating, and no join space is added."}]},{"heading":"The six kinds of field","paragraphs":[{"text":"Every app answers the two-character question in its own way, and the answer, not the app, decides what SpeakWith does. There are six kinds. The first three cover how a field reports its text, the next two cover how it accepts text, and the last one is out of reach."},{"text":"Legible. The field reports its text and the cursor honestly. The phrase gets the full rule: one space against a word, none against a space or an edge, and the spacing is right on both sides."},{"text":"Opaque. The field answers, but reports no text at all. An empty answer is just as likely to be an editor that hides its contents as a field that is actually empty, and the two are indistinguishable, so SpeakWith deliberately treats this as unreadable. Believing it would drop the join space and glue phrases together. The phrase lands with no space in front and the join space after, so prose still separates, and as soon as the field shows any text the next phrase gets the full rule. The first phrase into a field that reports nothing can still land against a word with no space."},{"text":"Silent. The field does not answer, because it has no text to report or because the app is busy. SpeakWith uses the same fallback as an opaque field. Your words are never dropped for want of an answer."},{"text":"Write-shy. The field reports its cursor but refuses a direct write. SpeakWith re-reads the field after each attempt. If the text is unchanged, it falls back to the clipboard and a paste. If it cannot tell what happened, it stops and says so rather than pasting twice."},{"text":"Trimming. The field accepts the paste but strips the leading space from pasted text, so phrases run together even though the read was honest. SpeakWith types the one leading space as a keystroke and pastes the rest. A keystroke is not pasted text, so no trimming applies to it, and in a field that keeps leading spaces the result is identical."},{"text":"Normalizing. The field collapses whitespace later, usually when a message is sent. Spacing that was right at the moment of typing is rewritten afterwards by the app. No way of inserting text can change this; the words still arrive, and the app decides how they are spaced on the way out."}]},{"heading":"What it reads, and what it never reads","paragraphs":[{"text":"The read is two characters, the one before the insertion point and the one after. SpeakWith does not read the document, the rest of the field, or what was on the clipboard before. When a phrase has to go through the clipboard, it is flagged so clipboard managers skip it, and the clipboard is put back afterwards if nothing else wrote to it in the meantime. A password field is detected before anything is written, and SpeakWith refuses to type into it, so a password never passes through the clipboard."}]},{"heading":"Where this applies","paragraphs":[{"text":"Typing into other apps is a feature of the direct Mac build. The App Store build is sandboxed, and macOS does not allow a sandboxed app to type into another one, so none of this page applies there. Your day document receives every phrase either way."}]}],"seeAlso":{"label":"See also: Reading live transcript corrections, for the marks SpeakWith puts on a settled line in its own window.","path":"guides/live-transcript-corrections"}},"languageLearning":{"eyebrow":"Guides","heading":"Practise a language aloud","intro":"Dictate in the language you are learning, and SpeakWith writes a translation under your own words. Your sentence stays where you said it, so you can read the pair together and see what you got right. This guide covers the two language settings, input and output, what the recorder shows you while it works, and the three things it cannot do yet.","diagramDark":"assets/guides/language-learning-annotated.svg?v=20261029a","diagramLight":"assets/guides/language-learning-annotated-light.svg?v=20261029a","diagramAlt":"Annotated diagram of multilingual dictation in SpeakWith, in four recreated panels with five numbered callouts. Settings under Engine shows the Dictation language section, with Spoken input language set to Deutsch. The live recorder header reads Recording, then Language: Deutsch. The AI sidebar shows the Polish heading with two chips beside it, Auto and a translate chip reading de to en. Settings under Session AI shows Translate polish into set to English, and In the day document set to Both versions. At the foot, a day document holds one dictated German line with its English translation written as a block beneath it, reading: I want to try something this week.","sections":[{"heading":"Which builds have it","paragraphs":[{"text":"Multilingual dictation is pre-release. It is in the direct download of the Mac app (the Gumroad build, with its own engine) and in the iPhone app, which has not reached the App Store yet. The Mac App Store build does not have it. If you installed SpeakWith from the Mac App Store, none of the settings on this page are there."}]},{"heading":"Choose an input and an output language","paragraphs":[{"text":"There is nothing to turn on first: picking the languages is the whole setup. The walkthrough that follows is written for the Mac; the iPhone has its own section further down."},{"text":"There are two language settings, and they are deliberately not the same list. The input is Spoken input language, in Settings under Engine: the language the engine listens in. It is set per project, so one project can sit in German while another stays in English. The output is Translate polish into, in Settings under Session AI in the section Feedback and polish: the language a polish writes. Leave it empty and a polish does not translate."},{"text":"Think of them as a source and a target. Both directions work: dictate in German and read it in English, or dictate in English and read it in German. To practise a language, set the spoken input to the language you are learning and the translation to the one you know, then say your sentence."},{"text":"If the menus are longer than you need, Settings under Languages has two tick lists, Spoken input and Translate into. They only decide which rows the two menus draw, not what you dictate in or translate into. Your current pick always stays in its menu, even when you untick it."}]},{"heading":"What the panel and the chip tell you","paragraphs":[{"text":"On the Mac, while you record, the live panel header shows Language: and the language the engine will actually use. It reports what the engine will do, not what the setting says. It can name a specific language, read Automatic when the engine detects the language itself, or read English on an engine that transcribes English alone, where there is nothing to choose."},{"text":"In the Mac's AI sidebar, the Polish heading carries a small chip that says whether this polish will translate. When translation is off it reads Translate: Off. When it is on, it shows the pair as a source and a target. The chip is there even when translate is off, because knowing that it will not translate is an answer you need too. Press it and the same settings open in one place. The chip is a Mac feature; the iPhone does not have it."}]},{"heading":"What lands in the day document","paragraphs":[{"text":"Settings under Session AI has a row called In the day document, with two choices. Both versions is the default: your dictation stays where it landed, and the translation is written as a new block under it. This is the shape that makes the pair readable when you are learning a language, and it is the one this guide recommends. Say your sentence in the language you are practising, and the page keeps it with the translation beneath. In the figure above, that translation reads: I want to try something this week."},{"text":"Translation only clears your own words and leaves the translation standing alone. This is lossy. Your original is gone from the page, and a regenerate afterwards will refuse, because the app finds your original by its words and the words are no longer there. Choose it only when you want the translation and nothing else."},{"text":"Translating the same take a second time replaces the first translation. It does not stack a second one under it."}]},{"heading":"On the iPhone","paragraphs":[{"text":"The iPhone app has the same pair of languages, in its own places. Open Settings and choose Live Dictation: the row Spoken input is the language the recorder listens in. Translate polish into is in Settings under Session AI, and the tick lists that shorten the menus are in Settings under Languages. The day document choice, Both versions or Translation only, works the same as on the Mac."},{"text":"Some things differ. The phone transcribes with Apple Speech on the device, and its recorder has its own language menu rather than a Language: line in a panel header. There is no translate chip on the Polish heading, so the settings rows are the place to check whether a polish will translate. The translation uses the AI service included with SpeakWith Pro. An OpenAI API key you provide is an alternative. There is no Ollama option on the phone."}]},{"heading":"What it cannot do yet","paragraphs":[{"text":"On the Mac, not every engine can hear every language. An engine that transcribes English only stays in English whatever the setting says, and the panel header tells you so by reading English."},{"text":"On the Mac and the iPhone alike, the first take in a new language pauses while the on-device model for that language downloads over the network. It is slow the first time and instant afterwards. The pause is the download, not the app hanging."},{"text":"On the Mac, dictating in a language other than English turns the live second pass off, because the second pass decodes English only."}]},{"heading":"Where the translation happens","paragraphs":[{"text":"Transcription happens on your device. The translation does not. It is a language-model call, like the other optional AI features. On the Mac it goes to the AI service included with a monthly membership, to an OpenAI API key you provide, or to a local Ollama model you run yourself; on iPhone and iPad, SpeakWith Pro includes that service."}]}],"seeAlso":{"path":"guides/recorder-badge","label":"See also: reading the recorder badge, the other lines the live panel header shows."}},"aiUsage":{"eyebrow":"Guides","heading":"Viewing your AI usage","intro":"AI Usage is the window that shows how much of the included AI a monthly membership has used, and what this Mac spent it on. The figures in the diagram were invented for this guide. On the Mac, open the app menu and choose AI Usage…. On iPhone and iPad that reading sits under Settings, Session AI. You can also press and hold the meter row on the live panel.","diagramDark":"assets/guides/ai-usage-annotated.svg?v=20261105a","diagramLight":"assets/guides/ai-usage-annotated-light.svg?v=20261105a","diagramAlt":"Annotated example of the AI Usage window. The chrome reads Example. A gauge shows 47 percent beside the words this month. A box lists 126 polishes, 58 titles, and 7 regenerates, plus 12 calls on your own key, and the line Counted on this Mac. A bar chart for 1 to 5 November has a grey earlier column, with By feature selected beside By model. Six callouts name the period, the all-device gauge, counts rather than tokens, this Mac, the feature or model switch, and the grey column.","sections":[{"heading":"The gauge is every device","paragraphs":[{"text":"The bar at the top is the share of included AI used in the current period. A paid month labels that period this month. A trial labels it this week. There is no 1-day, 7-day, or 30-day control. The membership is in one period, and the window shows that period."},{"text":"The percentage is the service's figure for the whole membership, every Mac and every iPhone on it. A polish on the phone and a title on the Mac move the same bar. The window prints a percentage. The terms guarantee no particular allowance, so no token ceiling appears."}]},{"heading":"What you did with it","paragraphs":[{"text":"Under the gauge, a box names the work the allowance paid for on this Mac. The line counts calls, and in the diagram it reads 126 polishes, 58 titles, and 7 regenerates. Tokens are the unit on the chart below."},{"text":"Calls on an OpenAI key you supply are a second line. The plan is not charged for them, and they stay outside the gauge. That line reads 12."},{"text":"The box ends with Counted on this Mac. Calls from the phone sit inside the percentage. They do not appear in this list."}]},{"heading":"Each day, on this Mac","paragraphs":[{"text":"The columns use the same scope as those counts: this Mac. Each column is one day in the period, stacked by the kind of work. By feature colours them Polish, Titles, and Regenerate. By model recolours those days by which model answered. That pair is the only picker."},{"text":"The grey column, marked earlier, is usage this Mac has already counted that the chart cannot split into a day, a feature, or a model. It still belongs in the Mac's total."}]},{"heading":"Before any usage","paragraphs":[{"text":"Until the membership has used the service, the gauge stays off the page, and so does the chart. What remains is the standing note that the service comes with every plan."},{"text":"Development builds can show a row for the cost of the service. That row is absent from the window everyone else sees, and this guide leaves it undescribed."}]},{"heading":"The names on the chart","paragraphs":[{"text":"Feature names are the app's own list: Polish, Regenerate, Translate, Feedback, Titles, Sends, and Other. The figure draws three of them. A real window lists only the kinds of work that have actually run on this Mac."}]},{"heading":"On the Mac and on the iPhone","paragraphs":[{"text":"On the Mac, the command is AI Usage… in the app menu. Holding the live panel's meter row for half a second opens the same window. On iPhone and iPad, the page is under Settings, then Session AI."},{"text":"Opened from either device, the percentage stays the membership total, and the counts and bars stay the Mac's itemised record. The callouts keep that split visible."}]},{"heading":"These figures are an example","paragraphs":[{"text":"The gauge at 47 percent, the counts 126, 58, 7, and 12, the days from 1 November through 5 November, and the grey column at 38,000 were drawn for this page. They are a sample. They record no real membership, and they state no size for the allowance."}]}],"seeAlso":[{"path":"pricing","label":"See also: pricing, where a monthly membership includes the allowance."},{"path":"privacy","label":"See also: privacy, where the included AI service and its allowance are described."}]},"ollamaSetup":{"eyebrow":"Guides","heading":"Set up Ollama on your Mac","intro":"Ollama is an app that runs a language model on your Mac. SpeakWith can ask it for a session title and a polish, and, on the direct download, for the short summary above Related. There is no API key, and the transcript stays on the machine. You give up the hosted model's punctuation and the way it phrases a title. The names in the drawings are examples.","examplesLabel":"For example","diagramDark":"assets/guides/ollama-setup-annotated.svg?v=20261113a","diagramLight":"assets/guides/ollama-setup-annotated-light.svg?v=20261113a","diagramAlt":"Annotated example of Ollama beside SpeakWith. A terminal lists llama3.1:8b, qwen3:8b, and nomic-embed-text. Settings, Session AI, has Provider set to Ollama, Title model llama3.1:8b, an empty Polish model, Context 16k, and Keep warm 15 minutes. The AI sidebar shows Warm now, Unload, and a red line reading Ollama HTTP 404 model 'llama3.1' not found. Seven callouts name the list, the embedding model, the provider switch, the colon in the tag, context memory, keep warm, and that red line.","sections":[{"heading":"Why a local model","paragraphs":[{"text":"A monthly membership's allowance is not spent, and the session text is not sent to a service. That is the reason to flip the switch. A local model is not a discount copy of the hosted one."},{"text":"Open Settings, Session AI, and set Provider to Ollama. Titles and polish follow that one choice together. Feedback has no model row of its own. It uses the Title model tag."},{"text":"The rest of this page is the Mac. iPhone and iPad have no Ollama provider, and they cannot reach a model running on your computer."}],"steps":[]},{"heading":"Install it, and leave it running","paragraphs":[{"text":"Confirm the app from the menu bar and from Terminal before you pull a model."}],"figureDark":"assets/guides/ollama-setup-install.svg?v=20261113a","figureLight":"assets/guides/ollama-setup-install-light.svg?v=20261113a","figureAlt":"A menu bar with an ollama item whose menu reads ollama is running, and a Terminal window showing ollama --version with an example version number. Callouts mark the menu-bar daemon and the version check.","figureWidth":1280,"figureHeight":520,"steps":[{"title":"Install Ollama.","text":"Use the installer from Ollama. A menu-bar item appears, and the app is set to open at login. That item is the daemon SpeakWith talks to.","examples":["After a restart the item should already be up, without you opening Ollama by hand."]},{"title":"Ask for the version.","text":"In Terminal, run ollama --version. A version line means the command is on your path. The number in the drawing is an example. Any current release is enough.","examples":["command not found means the install did not land on your path, or this Terminal was opened before the install finished. Open a new window and try again."]},{"title":"Do not quit that menu-bar item.","text":"SpeakWith will not launch Ollama for you. Quitting the item is what later shows up as a connection failure, with no title written.","examples":[]}]},{"heading":"Pull a tag, then read the list","paragraphs":[{"text":"The NAME column of ollama list is the only menu there is. SpeakWith never asks the daemon which tags are installed, so the field in Settings is plain text."}],"figureDark":"assets/guides/ollama-setup-pull.svg?v=20261113a","figureLight":"assets/guides/ollama-setup-pull-light.svg?v=20261113a","figureAlt":"A terminal pulling qwen3:8b, with a progress bar at 67 percent and then success, above ollama list. The new qwen3:8b row is outlined and the :8b suffix is highlighted. Callouts mark the download and the colon.","figureWidth":1280,"figureHeight":560,"steps":[{"title":"Pull a model that can chat.","text":"llama3.1:8b and qwen3:8b are the tags that suit a title. The first pull downloads the weights, several gigabytes. An embedding model such as nomic-embed-text can appear in the list and still cannot write a title.","examples":["ollama pull llama3.1:8b","ollama pull qwen3:8b"]},{"title":"Read ollama list.","text":"Copy from the NAME column. Size is only there so you can see what the download cost in disk. SpeakWith does not show this table.","examples":[]},{"title":"Keep the colon.","text":"llama3.1:8b and llama3.1:latest are different tags. The Title model field ships as llama3.1, and a name with no colon is treated as that name plus :latest. A Mac that pulled only llama3.1:8b will refuse llama3.1.","examples":["The refusal names the tag you asked for: model 'llama3.1' not found.","Pasting llama3.1:8b, colon and all, is the fix."]}]},{"heading":"Type that tag into SpeakWith","paragraphs":[{"text":"The Ollama section is in Settings, Session AI, and only after Provider is set to Ollama. Its first sentence says the daemon must be running, and it prints the address on this Mac. There is no field for that address, and nothing in Settings changes it."}],"figureDark":"assets/guides/ollama-setup-settings.svg?v=20261113a","figureLight":"assets/guides/ollama-setup-settings-light.svg?v=20261113a","figureAlt":"The Ollama section of Settings, Session AI. Title model reads llama3.1:8b. Polish model shows the blank placeholder. Context shows 16k and Keep warm shows 15 minutes, as an example. Callouts name the typed tag, a different polish tag, context memory, and how long the model stays loaded. A split at the bottom shows title and polish sharing one provider.","figureWidth":1480,"figureHeight":720,"steps":[{"title":"Title model.","text":"Replace the placeholder with a NAME from ollama list, colon included. llama3.1:8b is the usual replacement for the shipped llama3.1.","examples":["Leave the field as llama3.1 only when ollama list actually has llama3.1:latest."]},{"title":"Polish model.","text":"Empty means polish reuses the Title model tag. Type a second tag only when polish should run on a different model. The first polish on that other tag waits for a cold load. Keep warm, the last row, holds that same tag only. Warming both would have the daemon drop one to keep the other.","examples":[]},{"title":"One provider for both jobs.","text":"Polish cannot stay on OpenAI once titles are local. The Provider row is the only switch, and it covers both.","examples":[]}]},{"heading":"Context, and how long it stays loaded","paragraphs":[{"text":"Context offers 4k, 8k, 16k, and 32k. A fresh install starts at 16k, which is what the drawing shows. Each title asks for a window big enough for that session, and never bigger than the step you picked. A larger step reserves more memory. A short session does not fill the step. When the text does not fit, the AI sidebar says so before you generate, and the heading is taken from the start of the session."},{"text":"Keep warm is how long the title model stays in memory after a title: Ollama default, 15 minutes, 1 hour, 4 hours, or Until quit. A fresh install uses Ollama default, leaving the timing to Ollama. The drawing picks 15 minutes only so the row shows a duration. Until quit holds the model until you quit SpeakWith, and SpeakWith releases it on the way out."},{"text":"Changing Context reloads the model even when the tag is the same. Count on the same wait as a first load."}],"steps":[]},{"heading":"Warm it before the first title","paragraphs":[{"text":"Warm now sits in the AI sidebar, next to the session title. It loads the title model at the context the following title will request, so Generate finds the model already resident. An 8B model can take about a minute the first time. Spend that wait on Warm now."},{"text":"Unload frees the memory. If nothing was loaded, the press is harmless."},{"text":"The line under the model name is the fit report for the session you have selected. Orange means the cap will trim it."}],"steps":[]},{"heading":"The summary above Related","paragraphs":[{"text":"Finding earlier sessions always runs on the Mac, with a model that lives inside SpeakWith. The paragraph above that list is a separate request. The direct download can hand it to Ollama. The Mac App Store build has no such control, which is why the drawing carries a banner."},{"text":"In Settings, Related, under Summary model, choose On this Mac. Local summary model is another free-text tag. Leave it blank and the summary follows Title model. A different tag starts cold, and a different context size reloads the model even when the name matches."},{"text":"With On this Mac selected, that paragraph is written locally and the allowance is untouched. OpenAI, the other item in the menu, sends titles and short excerpts off the machine and meters the call."}],"figureDark":"assets/guides/ollama-setup-related.svg?v=20261113a","figureLight":"assets/guides/ollama-setup-related-light.svg?v=20261113a","figureAlt":"Settings, Related, Summary model, with On this Mac selected and Local summary model left blank. A banner across the bottom reads Not in the Mac App Store build. Callouts name the local choice, the separate tag, and the banner.","figureWidth":1280,"figureHeight":640,"steps":[]},{"heading":"Two lines you may see in red","paragraphs":[{"text":"A missing tag. The sidebar shows Ollama HTTP 404, then the daemon's note that the model was not found, in the shape model 'llama3.1' not found. The usual cause is the shipped default: the field still says llama3.1, you pulled llama3.1:8b, and the daemon looks for llama3.1:latest. Paste the NAME column in full."},{"text":"The daemon is stopped. The line reads cannot connect to 127.0.0.1. No heading is written. Open the menu-bar item again. There is no Settings row that starts Ollama."},{"text":"A name that cannot chat fails too. If Title model is the embedding tag from the pull section, switch it to a chat model."}],"steps":[]},{"heading":"What never calls Ollama","paragraphs":[{"text":"Transcription. The recording and the transcript are produced on the device. The daemon is not in that path."},{"text":"Matching earlier sessions. That search never consults Ollama, including when an embedding tag is what you pulled."},{"text":"iPhone and iPad. Those apps cannot reach Ollama at all."}],"steps":[]}],"seeAlso":[{"path":"guides/ai-usage","label":"See also: viewing your AI usage, the allowance a local model does not spend."},{"path":"privacy","label":"See also: privacy, what is sent when you choose a hosted model instead."}]}}`),W={agentLists:{eyebrow:"Technical",heading:"Project and model lists",intro:"On the Agent tab of SpeakWith from Gumroad, Destination has three menus: Agent, Project, and Model. SpeakWith does not go looking for folders or models on its own. A program on your Mac tells it what to list, over one local address, and this page shows what that program sends. It is written for people who write such a program. If you only use the Agent tab, the Send to agent guide is the page to read.",sections:[{heading:"Before you start",paragraphs:[{text:"The Engine that ships with SpeakWith from Gumroad keeps a small catalog service on a loopback port. It starts with the Engine and stays up when you close the SpeakWith window, so a list pushed while the window is closed is there when it opens again. The service listens on this Mac only. Nothing on this page leaves the machine.",isHtml:!1},{text:`<p>The Engine picks the port, so read it off the running service and keep it in a shell variable. Every command on this page is written against that variable:</p><pre><code>SW_CATALOG="http://$(lsof -nP +c 0 -iTCP -sTCP:LISTEN \\
  | grep -iE 'Agent.*Catalog' | awk '{print $(NF-1)}')"
echo "$SW_CATALOG"</code></pre><p>That prints a loopback address and a port. If it prints <code>http://</code> and nothing more, the Engine is not running, and every call on this page needs it. Start the Engine and try again.</p><p>Then check that the service answers:</p><pre><code>curl "$SW_CATALOG/health"</code></pre><p>The answer is <code>{"ok":true,"role":"agent_catalog"}</code>.</p>`,isHtml:!0}]},{heading:"Projects",paragraphs:[{text:"The Project menu is filled by one call. It replaces the list you sent last time with the one you send now, so send everything you want listed, every time.",isHtml:!1},{text:`<p>Send the folders you know, whole, under a name of your own as the publisher:</p><pre><code>curl -X PUT "$SW_CATALOG/catalog/menus" \\
  -H 'Content-Type: application/json' \\
  -d '{
    "v": 1,
    "publisher": "my-session-manager",
    "projects": [
      {
        "id": "lighthouse-book",
        "path": "/Users/you/Writing/lighthouse-book",
        "label": "lighthouse-book",
        "last": 1790720000,
        "section": "recent"
      },
      {
        "id": "field-notes",
        "path": "/Users/you/Research/field-notes",
        "label": "field-notes",
        "section": "other"
      }
    ]
  }'</code></pre><p>Each row has an <code>id</code>, a <code>path</code>, and a <code>label</code>. The label is the text in the menu. Two fields are optional: <code>last</code> is the Unix time, in seconds, the folder was last worked in, and <code>section</code> is <code>recent</code> or <code>other</code>.</p>`,isHtml:!0},{text:"What you see on the Agent tab: rows marked recent, with a last time, appear under Recent, each with how long ago that was, such as 2 h ago. Every other row appears under All projects. When nothing was picked before, the first row is picked for you. A pick that is still in the new list stays picked.",isHtml:!1},{text:"A folder someone adds from the app, through Add folder… under Project, is not yours to replace.",isHtml:!1},{text:`<p>SpeakWith sends that folder as one call of its own and marks the row manual, so your next menus push leaves it in the list. You can make the same call yourself. The folder has to exist on this Mac.</p><pre><code>curl -X POST "$SW_CATALOG/catalog/projects" \\
  -H 'Content-Type: application/json' \\
  -d '{ "path": "/Users/you/Writing/lighthouse-book", "label": "lighthouse-book" }'</code></pre>`,isHtml:!0},{text:"The menus push replaces your projects and your own model rows. If you send destinations, it replaces those as a whole. It does not touch model rows another agent advertised, and it never changes a pick that is still a row.",isHtml:!1}]},{heading:"Models",paragraphs:[{text:"The Model menu reads Agent default until some list arrives. There are two ways to hand one over. Use the first when your program is the one filling the Project menu anyway. Use the second when your program is the agent itself, connected over ACP.",isHtml:!1},{text:"<p><strong>On the same menus push.</strong></p>",isHtml:!0},{text:`<p>Add a <code>models</code> list to the menus push above. Each row has an <code>id</code>, the value your program understands when the pick is handed back, and a <code>label</code>, the text in the menu. A <code>description</code> is optional.</p><pre><code>"models": [
  { "id": "claude-opus-5-5", "label": "Opus 5.5" },
  { "id": "claude-sonnet-5-5", "label": "Sonnet 5.5", "description": "Faster, for a second pass" }
]</code></pre><p>Rows sent this way are filed under your publisher. Your next push replaces them and leaves the rows other agents advertised alone.</p>`,isHtml:!0},{text:"<p><strong>On session/new.</strong></p>",isHtml:!0},{text:`<p>An agent connected over ACP answers <code>session/new</code>. Put the models in that answer as a <code>configOptions</code> entry whose <code>category</code> is <code>model</code>. SpeakWith reads it and stores the list under that agent with <code>PUT /catalog/models/{agent}</code>. Your program never calls the catalog for models at all.</p><pre><code>{
  "sessionId": "s-1",
  "configOptions": [
    {
      "id": "model",
      "category": "model",
      "currentValue": "claude-opus-5-5",
      "options": [
        { "value": "claude-opus-5-5", "name": "Opus 5.5", "description": "Most capable" },
        { "value": "claude-sonnet-5-5", "name": "Sonnet 5.5" }
      ]
    }
  ]
}</code></pre><p>Each <code>value</code> becomes the model id and each <code>name</code> the label; leave <code>name</code> out and the value is shown. <code>currentValue</code> names the row the agent is on right now. SpeakWith also reads the older <code>models.availableModels</code> shape, but when an answer carries both, the <code>configOptions</code> entry wins.</p>`,isHtml:!0},{text:"What you see on the Agent tab: with the first way, the Model menu fills as soon as your push lands, before any agent has been contacted. With the second, it fills once that agent has answered session/new, which happens when a session is opened with it. Either way the status line ends in default model until someone picks a row, and a pick that is still in the list stays picked across pushes.",isHtml:!1}]},{heading:"Reading it back",paragraphs:[{text:'<p>Every write answers with the whole catalog as it now stands, so you never need a second call to see what your change settled to. You can also read it at any time, and the answer includes the current pick as <code>selection</code>, with <code>agent</code>, <code>projectPath</code>, and <code>modelId</code>:</p><pre><code>curl "$SW_CATALOG/catalog"</code></pre><p>To be told when something changes, open <code>$SW_CATALOG/events</code>. It is a server-sent event stream with one <code>catalog</code> event per change. The event carries no detail; read the catalog again when it arrives.</p>',isHtml:!0}]}],seeAlso:{label:"See also: Send to agent, the guide that follows one job from the Outline to the message the agent receives.",path:"guides/send-to-agent"}}},P=JSON.parse(`{"heading":"Privacy Policy","meta":"Last updated: November 2026","intro":"SpeakWith is built around a simple principle: your words are yours. This policy explains what SpeakWith does and does not do with the recordings, transcripts, and documents you create. November 2026 changes: a new section describes the AI service included with a monthly membership, which sends transcript text to IKI Systems and then to OpenAI. The policy also now covers Related sessions on the Mac, which matches on your device and can send excerpts from earlier days to a language model for a short summary.","sections":[{"heading":"Your recordings are processed on your device","paragraphs":[{"text":"SpeakWith records, transcribes, organises, and searches entirely on your own device, whether that is your Mac or your iOS device. Turning speech into text, shaping it into your daily document, and answering your searches all happen locally. SpeakWith does not need an internet connection to do its core work, and it does not send your recordings to a server to be processed.","isHtml":false},{"text":"On the Mac, Related sessions is processed on your device too. When you turn it on, SpeakWith builds an index of your day documents and, while you dictate, compares what you have just said with that index to list earlier sessions on the same subject. The model that does the comparing is downloaded once and then runs on your Mac, and the index is a file on your Mac. Neither your words nor the index is sent anywhere for matching. Related sessions is off until you turn it on in Settings, and it is not part of the iPhone and iPad app.","isHtml":false},{"text":"Three optional features can send transcript text, never audio, to a language model: generating a session title, polishing a take, and, on the Mac, writing the short summary above the Related list. Titles and polish are off until you turn them on, and the summary comes with Related sessions, which is also off until you turn it on. All three can run through the AI service included with a monthly membership, described in the next section, or through your own OpenAI API key. On the Mac they can also use a local Ollama model, so nothing leaves your machine when you choose Ollama. On iPhone and iPad, session titles and polish use the AI service included with SpeakWith Pro. An OpenAI API key you provide is an alternative. Without Pro and without a key, nothing leaves the device.","isHtml":false},{"text":"One more feature can send transcript text off your device, and it works differently: Send to agent, on the Mac only. When you use it, the topics you have ticked in the Outline are handed to a coding agent already installed on your Mac, such as Claude Code, Cursor, Codex, or Gemini. SpeakWith hands that text to the program on your machine; the program is what contacts a provider, under your own account with whichever service it uses, and that provider then sees the topics you sent. What happens to the text from there is covered by that agent's own terms and privacy policy, not by this one. Nothing is sent until you press Send to agent, and nothing is sent if you never use the feature.","isHtml":false}]},{"heading":"The AI service included with a monthly membership","paragraphs":[{"text":"A monthly membership includes an AI service for session titles, polish, and, on the Mac, the Related summary, so you do not need to supply your own API key. When you use it, SpeakWith sends the transcript text for that step to a service run by IKI Systems, which forwards it to OpenAI to produce the title, the polished text, or the summary. Audio never leaves your device, and transcription still happens locally. If you turn on automatic polish, text is sent each time a take settles, not only when you press a button.","isHtml":false},{"text":"To confirm that your membership is current, the app sends your purchase credential over an encrypted connection, and the service checks it with the store that sold it. What the service keeps is a hash of that credential, which identifies your membership without being usable to buy or unlock anything, along with a hashed short-lived session token, your membership tier, and the time of first and most recent use. It does not store your name or your email address. It keeps a monthly total of the tokens each membership has used, so it can apply the allowance. That ledger holds counts, not your words. These records live in Amazon Web Services, in the US West (Oregon) region.","isHtml":false},{"text":"Separately, if your Mac holds a licence and has iCloud sync turned on, it asks the service to hold your purchase credential so that an iPhone signed into the same iCloud account can reach what you have paid for without ever storing the credential itself. This happens on any licensed Mac, whether or not you use an iPhone, and for a one-time purchase as well as a membership. The copy the service keeps is encrypted, and the only thing that can open it is a token your Mac generates and passes to your other devices through your own private iCloud storage. The service keeps no copy of that token, so it cannot read your credential on its own, only while one of your devices presents the token to check your licence. Your Mac replaces the token periodically. Removing your licence on that Mac deletes the stored copy; until you do, it stays.","isHtml":false},{"text":"SpeakWith can reach a language model three ways, and your text only passes through us on one of them: a local Ollama model on the Mac, where nothing leaves your device; an OpenAI API key you provide, where the text goes from the app straight to OpenAI and never through us; and the included service. For that third path our role is transit and nothing else. Our AI service never writes the text you send, or the text that comes back, to a log or to a database  -  not when a request succeeds, and not when it fails. Whatever we record about a failure describes the failure, never the text that was in flight. What OpenAI does with the text on its side is governed by <a href=\\"https://openai.com/policies/\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">OpenAI's terms and policies</a>.","isHtml":true},{"text":"The Related summary on the Mac sends more than the take in front of you. To write it, SpeakWith sends the lines you have just dictated together with, for each earlier session in the list, its date, its title, and an excerpt of its text clipped to 320 characters. Those excerpts come from earlier day documents, so text you dictated on other days is included. The summary is requested automatically once the list has stayed unchanged for a short wait that you can set, and each request counts against the same monthly allowance as titles and polish. It follows the same three paths as the other features. Choose On this Mac under Settings, Related, and a local Ollama model writes it with nothing leaving your Mac. With an OpenAI API key you provide, the text goes straight to OpenAI. With the included service, it passes through us in transit only. With no membership, no key, and no local model chosen, no summary is written and nothing is sent. The Mac App Store build does not write a summary at all.","isHtml":false},{"text":"The allowance is a monthly ceiling on how much text the service will process for one membership. If it runs out, or the service is unavailable, the app offers to use an OpenAI API key you provide instead, and nothing is sent until you choose. A one-time purchase and the 14-day free trial do not include the service; they use your own key or, on the Mac, a local Ollama model.","isHtml":false},{"text":"The app shows that reading in AI Usage. <a href=\\"/guides/ai-usage/\\">The guide to viewing your AI usage</a> walks through the window: which figures cover every device, and which ones are this Mac.","isHtml":true}]},{"heading":"No telemetry, analytics, or tracking in the app","paragraphs":[{"text":"The SpeakWith application does not include usage analytics, advertising, or behavioural tracking. We do not collect a record of how you use the app, what you record, or what you search for. There are no third-party trackers in the application.","isHtml":false},{"text":"This is a statement about the app itself. This website, which is separate software running in your browser, measures anonymous visitor counts; that is described under “The support website” below. Nothing measured on the website is connected to the app, and the app never reports usage to us. The one exception is the included AI service: when a monthly membership uses it, the service records the token totals needed to apply the allowance, as described above. That is billing bookkeeping for a feature you chose to use, not product analytics, and it records amounts, not content.","isHtml":false}]},{"heading":"Your files belong to you","paragraphs":[{"text":"Everything SpeakWith produces (your recordings, transcripts, and daily documents) is stored as ordinary files on your device. Open, copy, move, back up, or delete them with any tool you like.","isHtml":false}]},{"heading":"Crash reporting is opt-in only","paragraphs":[{"text":"If something in SpeakWith goes wrong, a diagnostic report can help us fix it. SpeakWith never sends such a report automatically. Crash and diagnostic reporting is strictly opt-in: nothing leaves your device unless you explicitly choose to send it, and you can decline or turn it off at any time.","isHtml":false}]},{"heading":"The support website","paragraphs":[{"text":"This website uses TelemetryDeck, a privacy-focused analytics service, to count page views and how often the download and pricing links are used. It tells us which pages people find useful. It is not used to profile you.","isHtml":false},{"text":"No cookies are set for analytics and no advertising or cross-site tracking identifiers are used. Visits are identified only by a random value that lives in your browser tab and is discarded when you close it, and TelemetryDeck anonymises that value before storing it. We see aggregate counts  -  pages, referrers, campaign links, browser and country  -  never individual visitors, and never anything you type.","isHtml":false},{"text":"Standard server request logs may exist at the hosting provider, as they do for any website.","isHtml":false}]},{"heading":"Changes to this policy","paragraphs":[{"text":"If this policy changes, the updated version will be posted here with a new date. Material changes will be summarised at the top of the page.","isHtml":false}]}]}`),I={heading:"Terms of Service",meta:"Last updated: November 2026",intro:"These terms govern your use of the SpeakWith application. By installing or using SpeakWith, you agree to them. Please read them carefully.",sections:[{heading:"Licence to use SpeakWith",paragraphs:[{text:"SpeakWith grants you a personal, non-exclusive, non-transferable licence to install and use the application on Mac computers and iOS devices you own or control, in accordance with these terms. You may not redistribute, resell, rent, or sublicense the application, or attempt to reverse engineer it except where that restriction is prohibited by law.",isHtml:!1}]},{heading:"Accuracy disclaimer",paragraphs:[{text:"SpeakWith converts speech to text using automated processing. Automated transcription is a powerful aid, but it is <strong>not guaranteed to be accurate or complete</strong>. Results depend on factors including recording quality, background noise, accents, specialist vocabulary, and the nature of what was said.",isHtml:!0},{text:"You should treat transcripts as a high-quality first draft to review and correct, not as a verbatim or certified record. Do not rely on SpeakWith's output for any purpose where an error could cause harm, loss, or legal consequence without independently verifying it.",isHtml:!1}]},{heading:"Your content",paragraphs:[{text:"You own the recordings, transcripts, and documents you create with SpeakWith. SpeakWith does not claim any rights over your content. You are responsible for what you record and for having the right to record it. Because your content is stored as files on your own device, you are also responsible for backing it up.",isHtml:!1}]},{heading:"The included AI service",paragraphs:[{text:"A monthly membership includes access to an AI service for session titles and polish. Using it is optional. The service sends the transcript text for that step to IKI Systems and then to OpenAI, as described in the Privacy Policy. A one-time purchase and the free trial do not include it.",isHtml:!1},{text:"The service comes with a monthly allowance. We do not guarantee any particular allowance, that it will cover your use, or that the service will be available at any given time. If the allowance is used up or the service is unavailable, the app lets you continue with your own API key. We may change the model the service uses, the allowance, or the way the allowance is measured, and we may withdraw the service with reasonable notice.",isHtml:!1},{text:"Titles and polished text are produced by an automated language model. They are suggestions, not a certified record, and the accuracy disclaimer above applies to them. Review what the service returns before you rely on it.",isHtml:!1},{text:"You keep ownership of the text you send and of what comes back. IKI Systems does not claim rights over either, and does not keep the text once the request completes.",isHtml:!1}]},{heading:'Provided "as is"',paragraphs:[{text:'SpeakWith is provided "as is" and "as available", without warranties of any kind, whether express or implied, including but not limited to warranties of merchantability, fitness for a particular purpose, and non-infringement. We do not warrant that the application will be uninterrupted, error-free, or that every recording will be processed successfully.',isHtml:!1}]},{heading:"Limitation of liability",paragraphs:[{text:'To the maximum extent permitted by law, SpeakWith and <a href="https://ikisystems.com/" target="_blank" rel="noopener noreferrer">IKI Systems</a> will not be liable for any indirect, incidental, special, or consequential damages, or for any loss of data, arising out of or related to your use of the application. Nothing in these terms excludes liability that cannot be excluded under applicable law.',isHtml:!0}]},{heading:"Changes to these terms",paragraphs:[{text:"These terms may be updated from time to time. The current version will always be posted here with its date. Continued use of SpeakWith after a change means you accept the updated terms.",isHtml:!1}]},{heading:"Auto-renewing subscription",paragraphs:[{text:"SpeakWith Pro on iPhone and iPad is an auto-renewing monthly subscription named SpeakWith Pro (product com.ikisystems.speakwith.pro.subscription). The App Store shows the price, in your local currency, before you subscribe. A 7-day free trial converts to the paid month unless you cancel. Payment is charged to your Apple Account. The subscription renews automatically unless cancelled at least 24 hours before the end of the period. Manage or cancel in the App Store app, under your account, then Subscriptions. Refunds are handled by Apple.",isHtml:!1},{text:"Pro includes session titles, polish, and a monthly AI allowance. Live dictation, day documents, search, and projects stay free and are not part of the subscription. The Mac app's Gumroad membership is a separate purchase. While it is active, this subscription also unlocks the direct Mac download on a Mac signed in to the same Apple Account, on the same terms as the monthly membership; likewise, an active Gumroad membership or one-time license unlocks SpeakWith Pro on iPhone and iPad signed in to the same Apple Account.",isHtml:!1}]}]},O={heading:"Something went wrong",lead:"This page hit an error. Reloading usually clears it.",leadRequest:"That request could not be completed. Reloading usually clears it.",leadStaleChunk:"The site was updated while this page was open, so part of it could no longer be loaded. Reloading picks up the new version.",reload:"Reload",home:"Back to home"},c={nav:f,app:b,links:k,seo:v,home:S,pricing:T,automation:A,guides:x,technical:W,privacy:P,terms:I,error:O},l={origin:"https://speakwith.ikisystems.com",defaultLocale:"en",locales:[{code:"en",prefix:"",htmlLang:"en",ogLocale:"en_US",endonym:"English"}],routes:[{path:"",seoKey:"home",localized:!0,priority:"1.0"},{path:"pricing",seoKey:"pricing",localized:!0,priority:"0.8"},{path:"automation",seoKey:"automation",localized:!0,priority:"0.6"},{path:"guides",seoKey:"guides",localized:!0,priority:"0.5"},{path:"guides/recorder-badge",seoKey:"guidesRecorderBadge",localized:!0,priority:"0.5"},{path:"guides/live-transcript-corrections",seoKey:"guidesLiveTranscriptCorrections",localized:!0,priority:"0.5"},{path:"guides/status-monitor",seoKey:"guidesStatusMonitor",localized:!0,priority:"0.5"},{path:"guides/send-to-agent",seoKey:"guidesSendToAgent",localized:!0,priority:"0.5"},{path:"guides/outline",seoKey:"guidesOutline",localized:!0,priority:"0.5"},{path:"guides/context-aware-insertion",seoKey:"guidesContextAwareInsertion",localized:!0,priority:"0.5"},{path:"guides/language-learning",seoKey:"guidesLanguageLearning",localized:!0,priority:"0.5"},{path:"guides/ai-usage",seoKey:"guidesAiUsage",localized:!0,priority:"0.5"},{path:"guides/ollama-setup",seoKey:"guidesOllamaSetup",localized:!0,priority:"0.5"},{path:"technical/agent-lists",seoKey:"technicalAgentLists",localized:!0,priority:"0.4"},{path:"privacy",seoKey:"privacy",localized:!1,priority:"0.3"},{path:"terms",seoKey:"terms",localized:!1,priority:"0.3"}]},M={},N=l.origin,d=l.defaultLocale,h=l.locales,m=l.routes,L=M,p=new Map;function H(t){const e=t??d,a=p.get(e);if(a)return a;const n=L[e],i=n?{...c,...n}:c;return p.set(e,i),i}function u(t){return h.find(e=>e.code===t)??h.find(e=>e.code===d)}function g(t,e){const a=m.find(s=>s.path===t),i=[a&&!a.localized?"":e.prefix,t].filter(Boolean);return i.length?`/${i.join("/")}/`:"/"}const C=h.length>1,R=h.filter(t=>t.prefix);function j(t){return t.split("#")[0].split("?")[0].split("/").filter(Boolean)}function D(t){const e=j(t),a=e.length?R.find(o=>o.prefix===e[0]):void 0,n=a??u(d),s=(a?e.slice(1):e).join("/");if(s==="404")return{locale:u(d),page:"404",localized:!1,notFound:!0};const r=m.find(o=>o.path===s);return!r||!r.localized&&a?{locale:n,page:s,localized:!1,notFound:!0}:{locale:n,page:s,localized:r.localized,notFound:!1,def:r}}function U(){const{pathname:t}=w(),{locale:e,page:a,localized:n,notFound:i}=D(t),s=H(e.code),r=[...h].sort((o,y)=>o.endonym.localeCompare(y.endonym)).map(o=>({locale:o,href:g(a,o),current:o.code===e.code}));return{locale:e,copy:s,page:a,pageIsLocalized:n&&!i,multilingual:C,path:o=>g(o,e),switcherLinks:r}}export{d as D,h as L,C as M,N as O,u as a,H as c,g as l,D as r,U as u};
